import { PrismaClient } from '@prisma/client';
import { activitiesData } from './src/lib/data/activities-data';
import { generateShortId, ShortIdPrefix } from './src/lib/id-generator';

const prisma = new PrismaClient();

async function main() {
    console.log("Starting Static Activities Seed...");

    const allActivities = Object.values(activitiesData).flat();
    console.log(`Found ${allActivities.length} static activities.`);

    for (const activity of allActivities) {
        if (!activity.id) {
            console.warn("Skipping activity without ID:", activity.title);
            continue;
        }

        const existing = await prisma.service.findUnique({
            where: { id: activity.id }
        });

        if (existing) {
            console.log(`Activity ${activity.id} already exists.`);
            // Optional: Update it? For now, we assume static data is source of truth if we want to sync.
            // Let's UPDATE it to ensure DB matches code.
            await prisma.service.update({
                where: { id: activity.id },
                data: {
                    title: activity.title,
                    description: activity.description,
                    price: activity.price,
                    category: activity.category,
                    rating: activity.rating,
                    reviews: activity.reviews,
                    duration: activity.duration,
                    location: activity.location,
                    images: activity.images || (activity.image ? [activity.image] : []),
                    features: activity.features,
                    included: activity.included,
                    whatToBring: activity.whatToBring,
                    tags: activity.tags,
                    // Handle complex objects as JSON
                    host: activity.host ? JSON.stringify(activity.host) : "Unknown",
                    itinerary: activity.itinerary ? JSON.stringify(activity.itinerary) : undefined,
                    // Extra fields stored in JSON or mapped if schema supports
                    // Schema doesn't have specific fields for 'programs' etc, so we might lose some data if not mapped effectively.
                    // But standard fields are covered.

                    // IMPORTANT: Ensure shortId exists
                    shortId: (existing as any).shortId || generateShortId(ShortIdPrefix.SERVICE),
                } as any
            });
            console.log(`Updated ${activity.id}`);
        } else {
            console.log(`Creating ${activity.id}...`);
            await prisma.service.create({
                data: {
                    id: activity.id, // KEEP the static ID
                    title: activity.title,
                    description: activity.description,
                    price: activity.price,
                    category: activity.category,
                    rating: activity.rating,
                    reviews: activity.reviews,
                    duration: activity.duration,
                    location: activity.location,
                    images: activity.images || (activity.image ? [activity.image] : []),
                    features: activity.features,
                    included: activity.included,
                    whatToBring: activity.whatToBring,
                    tags: activity.tags,
                    host: activity.host ? JSON.stringify(activity.host) : "Unknown",
                    itinerary: activity.itinerary ? JSON.stringify(activity.itinerary) : undefined,

                    shortId: generateShortId(ShortIdPrefix.SERVICE),
                } as any
            });
        }
    }

    console.log("Seeding complete.");
}

main()
    .catch((e) => {
        console.error(e);
        process.exit(1);
    })
    .finally(async () => {
        await prisma.$disconnect();
    });

'use server'

import prisma from '@/lib/prisma'
import { BookingStatus } from '@prisma/client'
import { revalidatePath } from 'next/cache'

export async function getBookings() {
    try {
        const bookings = await prisma.booking.findMany({
            orderBy: {
                date: 'desc',
            },
        })
        return { success: true, data: bookings }
    } catch (error) {
        console.error('Failed to fetch bookings:', error)
        return { success: false, error: 'Failed to fetch bookings' }
    }
}

export async function updateBookingStatus(id: string, status: BookingStatus) {
    try {
        await prisma.booking.update({
            where: { id },
            data: { status },
        })
        revalidatePath('/admin/bookings')
        revalidatePath('/admin/dashboard')
        return { success: true }
    } catch (error) {
        console.error('Failed to update booking status:', error)
        throw new Error('Failed to update booking status')
    }
}

export async function confirmBooking(id: string) {
    try {
        const booking = await prisma.booking.findUnique({
            where: { id },
            include: { user: true }
        });

        if (!booking) {
            return { success: false, error: 'Booking not found' };
        }

        await prisma.booking.update({
            where: { id },
            data: { status: 'CONFIRMED' },
        });

        // Send confirmation email
        try {
            const { emailService } = await import('@/services/email.service');
            await emailService.sendBookingConfirmation(
                booking.email,
                booking.name,
                booking.id,
                booking.activityTitle,
                booking.date,
                booking.guests,
                typeof (booking.totalPrice as any)?.toNumber === 'function'
                    ? (booking.totalPrice as any).toNumber()
                    : Number(booking.totalPrice)
            );
        } catch (error) {
            console.error('Failed to send confirmation email:', error);
        }

        revalidatePath('/admin/bookings');
        revalidatePath('/admin/dashboard');
        return { success: true };
    } catch (error) {
        console.error('Failed to confirm booking:', error);
        return { success: false, error: 'Failed to confirm booking' };
    }
}

export async function cancelBooking(id: string) {
    try {
        const booking = await prisma.booking.findUnique({
            where: { id }
        });

        if (!booking) {
            return { success: false, error: 'Booking not found' };
        }

        await prisma.booking.update({
            where: { id },
            data: { status: 'CANCELLED' },
        });

        // Send cancellation email
        try {
            const { emailService } = await import('@/services/email.service');
            await emailService.sendBookingCancellation(
                booking.email,
                booking.name,
                booking.activityTitle,
                booking.paymentStatus === 'PAID'
                    ? (typeof (booking.totalPrice as any)?.toNumber === 'function'
                        ? (booking.totalPrice as any).toNumber()
                        : Number(booking.totalPrice))
                    : undefined
            );
        } catch (error) {
            console.error('Failed to send cancellation email:', error);
        }

        revalidatePath('/admin/bookings');
        revalidatePath('/admin/dashboard');
        return { success: true };
    } catch (error) {
        console.error('Failed to cancel booking:', error);
        return { success: false, error: 'Failed to cancel booking' };
    }
}

export async function processBooking(id: string) {
    try {
        await prisma.booking.update({
            where: { id },
            data: { status: 'COMPLETED' },
        })
        revalidatePath('/admin/bookings')
        revalidatePath('/admin/dashboard')
        return { success: true }
    } catch (error) {
        console.error('Failed to process booking:', error)
        return { success: false, error: 'Failed to process booking' }
    }
}

export async function deleteBooking(id: string) {
    try {
        await prisma.booking.delete({
            where: { id },
        })
        revalidatePath('/admin/bookings')
        return { success: true }
    } catch (error) {
        console.error('Failed to delete booking:', error)
        return { success: false, error: 'Failed to delete booking' }
    }
}

'use client';

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Button } from '@/components/ui/button';
import { Download, TrendingUp, TrendingDown, DollarSign, Calendar, Users } from 'lucide-react';
import { format, subDays, startOfDay, endOfDay } from 'date-fns';
import { toast } from 'sonner';

interface AnalyticsData {
    revenue: {
        today: number;
        week: number;
        month: number;
        total: number;
        change: number;
    };
    bookings: {
        today: number;
        week: number;
        month: number;
        total: number;
        change: number;
    };
    users: {
        total: number;
        newThisWeek: number;
        change: number;
    };
    topServices: Array<{
        id: string;
        title: string;
        bookings: number;
        revenue: number;
    }>;
    recentTrends: Array<{
        date: string;
        bookings: number;
        revenue: number;
    }>;
}

export default function AnalyticsPage() {
    const [data, setData] = useState<AnalyticsData | null>(null);
    const [loading, setLoading] = useState(true);
    const [dateRange, setDateRange] = useState<'7d' | '30d' | '90d'>('30d');

    useEffect(() => {
        fetchAnalytics();
    }, [dateRange]);

    const fetchAnalytics = async () => {
        try {
            setLoading(true);
            const res = await fetch(`/api/admin/analytics?range=${dateRange}`);
            
            if (!res.ok) {
                const errorData = await res.json().catch(() => ({}));
                const errorMessage = errorData?.error?.message || `HTTP ${res.status}: Failed to fetch analytics`;
                console.error('Analytics API error:', errorMessage, errorData);
                toast.error(`Failed to load analytics: ${errorMessage}`);
                // Set empty data structure to show error state
                setData({
                    revenue: { today: 0, week: 0, month: 0, total: 0, change: 0 },
                    bookings: { today: 0, week: 0, month: 0, total: 0, change: 0 },
                    users: { total: 0, newThisWeek: 0, change: 0 },
                    topServices: [],
                    recentTrends: []
                });
                return;
            }
            
            const analyticsData = await res.json();
            // Handle both wrapped and unwrapped responses
            const data = analyticsData.data || analyticsData;
            
            // Validate data structure
            if (!data || typeof data !== 'object') {
                throw new Error('Invalid analytics data format');
            }
            
            setData(data);
        } catch (error) {
            console.error('Error fetching analytics:', error);
            const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
            toast.error(`Failed to load analytics: ${errorMessage}`);
            // Set empty data structure to show error state
            setData({
                revenue: { today: 0, week: 0, month: 0, total: 0, change: 0 },
                bookings: { today: 0, week: 0, month: 0, total: 0, change: 0 },
                users: { total: 0, newThisWeek: 0, change: 0 },
                topServices: [],
                recentTrends: []
            });
        } finally {
            setLoading(false);
        }
    };

    const exportBookings = async () => {
        try {
            const res = await fetch('/api/admin/bookings/export');
            if (!res.ok) throw new Error('Failed to export');
            const blob = await res.blob();
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `bookings-${format(new Date(), 'yyyy-MM-dd')}.csv`;
            document.body.appendChild(a);
            a.click();
            window.URL.revokeObjectURL(url);
            document.body.removeChild(a);
        } catch (error) {
            console.error('Export error:', error);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <div className="text-center">
                    <div className="w-16 h-16 border-4 border-[#FF5F00] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                    <p className="text-gray-600">Loading analytics...</p>
                </div>
            </div>
        );
    }

    if (!data) {
        return <div>No data available</div>;
    }

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Analytics Dashboard</h1>
                    <p className="text-muted-foreground">Comprehensive insights into your platform performance</p>
                </div>
                <Button onClick={exportBookings}>
                    <Download className="w-4 h-4 mr-2" />
                    Export Bookings
                </Button>
            </div>

            <Tabs value={dateRange} onValueChange={(v) => setDateRange(v as '7d' | '30d' | '90d')}>
                <TabsList>
                    <TabsTrigger value="7d">Last 7 Days</TabsTrigger>
                    <TabsTrigger value="30d">Last 30 Days</TabsTrigger>
                    <TabsTrigger value="90d">Last 90 Days</TabsTrigger>
                </TabsList>
            </Tabs>

            {/* Key Metrics */}
            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Total Revenue</CardTitle>
                        <DollarSign className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">Γé¼{data.revenue.total.toLocaleString()}</div>
                        <div className="flex items-center text-xs text-muted-foreground mt-1">
                            {data.revenue.change >= 0 ? (
                                <TrendingUp className="h-3 w-3 mr-1 text-green-500" />
                            ) : (
                                <TrendingDown className="h-3 w-3 mr-1 text-red-500" />
                            )}
                            <span className={data.revenue.change >= 0 ? 'text-green-500' : 'text-red-500'}>
                                {Math.abs(data.revenue.change).toFixed(1)}%
                            </span>
                            <span className="ml-1">vs previous period</span>
                        </div>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Total Bookings</CardTitle>
                        <Calendar className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{data.bookings.total}</div>
                        <div className="flex items-center text-xs text-muted-foreground mt-1">
                            {data.bookings.change >= 0 ? (
                                <TrendingUp className="h-3 w-3 mr-1 text-green-500" />
                            ) : (
                                <TrendingDown className="h-3 w-3 mr-1 text-red-500" />
                            )}
                            <span className={data.bookings.change >= 0 ? 'text-green-500' : 'text-red-500'}>
                                {Math.abs(data.bookings.change).toFixed(1)}%
                            </span>
                            <span className="ml-1">vs previous period</span>
                        </div>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Total Users</CardTitle>
                        <Users className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{data.users.total}</div>
                        <p className="text-xs text-muted-foreground mt-1">
                            {data.users.newThisWeek} new this week
                        </p>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Avg. Booking Value</CardTitle>
                        <DollarSign className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">
                            Γé¼{data.bookings.total > 0 
                                ? (data.revenue.total / data.bookings.total).toFixed(2)
                                : '0.00'
                            }
                        </div>
                        <p className="text-xs text-muted-foreground mt-1">
                            Per booking
                        </p>
                    </CardContent>
                </Card>
            </div>

            {/* Top Services */}
            <Card>
                <CardHeader>
                    <CardTitle>Top Performing Services</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="space-y-4">
                        {data.topServices.length > 0 ? (
                            data.topServices.map((service, index) => (
                                <div key={service.id} className="flex items-center justify-between border-b pb-4 last:border-0 last:pb-0">
                                    <div className="flex items-center gap-4">
                                        <div className="w-8 h-8 rounded-full bg-[#FF5F00]/10 flex items-center justify-center font-bold text-[#FF5F00]">
                                            {index + 1}
                                        </div>
                                        <div>
                                            <p className="font-medium">{service.title}</p>
                                            <p className="text-sm text-muted-foreground">
                                                {service.bookings} bookings
                                            </p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="font-bold">Γé¼{service.revenue.toFixed(2)}</p>
                                        <p className="text-xs text-muted-foreground">Revenue</p>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <p className="text-sm text-muted-foreground">No data available</p>
                        )}
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { ArrowLeft, Save, Eye, Upload } from 'lucide-react'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { Switch } from '@/components/ui/switch'
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from '@/components/ui/select'
import {
    Card,
    CardContent,
    CardDescription,
    CardHeader,
    CardTitle,
} from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import Image from 'next/image'
import { toast } from 'sonner'

export default function NewBlogPostPage() {
    const router = useRouter()
    const [loading, setLoading] = useState(false)
    const [saving, setSaving] = useState(false)
    const [preview, setPreview] = useState(false)
    const [uploading, setUploading] = useState(false)

    const [formData, setFormData] = useState({
        title: '',
        slug: '',
        excerpt: '',
        content: '',
        coverImage: '',
        category: '',
        featured: false,
        metaTitle: '',
        metaDescription: '',
        keywords: [] as string[],
    })

    const [errors, setErrors] = useState<Record<string, string>>({})

    const generateSlug = (title: string) => {
        return title
            .toLowerCase()
            .replace(/[^a-z0-9\s-]/g, '')
            .replace(/\s+/g, '-')
            .replace(/-+/g, '-')
            .trim()
    }

    const handleTitleChange = (value: string) => {
        setFormData(prev => ({
            ...prev,
            title: value,
            slug: prev.slug || generateSlug(value)
        }))
        if (errors.title) setErrors(prev => ({ ...prev, title: '' }))
    }

    const handleSlugChange = (value: string) => {
        setFormData(prev => ({ ...prev, slug: value }))
        if (errors.slug) setErrors(prev => ({ ...prev, slug: '' }))
    }

    const handleKeywordAdd = (keyword: string) => {
        if (keyword.trim() && !formData.keywords.includes(keyword.trim())) {
            setFormData(prev => ({
                ...prev,
                keywords: [...prev.keywords, keyword.trim()]
            }))
        }
    }

    const handleKeywordRemove = (index: number) => {
        setFormData(prev => ({
            ...prev,
            keywords: prev.keywords.filter((_, i) => i !== index)
        }))
    }

    const validate = () => {
        const newErrors: Record<string, string> = {}
        if (!formData.title.trim()) newErrors.title = 'Title is required'
        if (!formData.slug.trim()) newErrors.slug = 'Slug is required'
        if (!formData.excerpt.trim()) newErrors.excerpt = 'Excerpt is required'
        if (!formData.content.trim()) newErrors.content = 'Content is required'
        if (!formData.coverImage.trim()) newErrors.coverImage = 'Cover image is required'
        setErrors(newErrors)
        return Object.keys(newErrors).length === 0
    }

    const handleSave = async (publish: boolean = false) => {
        if (!validate()) return

        setSaving(true)
        try {
            const payload = {
                ...formData,
                publishedAt: publish ? new Date().toISOString() : null,
            }

            const res = await fetch('/api/admin/blog', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
            })

            if (!res.ok) {
                const error = await res.json()
                throw new Error(error.error || 'Failed to create post')
            }

            const post = await res.json()
            toast.success(publish ? 'Post published successfully!' : 'Post saved as draft!')
            router.push('/admin/blog')
        } catch (error: any) {
            console.error('Failed to save post', error)
            toast.error(error.message || 'Failed to save post')
        } finally {
            setSaving(false)
        }
    }

    const handleCloudinaryUpload = async (file: File) => {
        setUploading(true)
        try {
            // Get upload signature from server
            const signRes = await fetch('/api/admin/cloudinary/signature')
            if (!signRes.ok) throw new Error('Failed to get upload signature')
            const { signature, timestamp, apiKey, cloudName, uploadPreset } = await signRes.json()

            const formData = new FormData()
            formData.append('file', file)
            formData.append('api_key', apiKey)
            formData.append('timestamp', timestamp.toString())
            formData.append('signature', signature)
            formData.append('upload_preset', uploadPreset)

            const uploadRes = await fetch(
                `https://api.cloudinary.com/v1_1/${cloudName}/auto/upload`,
                { method: 'POST', body: formData }
            )

            if (!uploadRes.ok) throw new Error('Upload failed')
            const result = await uploadRes.json()
            setFormData(prev => ({ ...prev, coverImage: result.secure_url }))
            toast.success('Image uploaded successfully!')
        } catch (error: any) {
            console.error('Upload failed', error)
            toast.error(error.message || 'Upload failed')
        } finally {
            setUploading(false)
        }
    }

    if (loading) {
        return (
            <div className="space-y-6">
                <Skeleton className="h-8 w-32" />
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div className="lg:col-span-2 space-y-6">
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-32 w-full" />
                        <Skeleton className="h-64 w-full" />
                    </div>
                    <div className="space-y-6">
                        <Skeleton className="h-64 w-full" />
                        <Skeleton className="h-48 w-full" />
                    </div>
                </div>
            </div>
        )
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <Link href="/admin/blog">
                        <Button variant="ghost" size="sm">
                            <ArrowLeft className="h-4 w-4 mr-2" />
                            Back to Posts
                        </Button>
                    </Link>
                    <div>
                        <h1 className="text-2xl font-bold text-charcoal">New Blog Post</h1>
                        <p className="text-sm text-medium-gray">Create a new blog article</p>
                    </div>
                </div>
                <div className="flex items-center gap-2">
                    <Button
                        variant="outline"
                        onClick={() => setPreview(!preview)}
                        className="gap-2"
                    >
                        <Eye className="h-4 w-4" />
                        {preview ? 'Edit' : 'Preview'}
                    </Button>
                    <Button
                        variant="outline"
                        onClick={() => handleSave(false)}
                        disabled={saving}
                        className="gap-2"
                    >
                        <Save className="h-4 w-4" />
                        {saving ? 'Saving...' : 'Save Draft'}
                    </Button>
                    <Button
                        onClick={() => handleSave(true)}
                        disabled={saving}
                        className="gap-2"
                    >
                        <Save className="h-4 w-4" />
                        {saving ? 'Publishing...' : 'Publish'}
                    </Button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Main Content */}
                <div className="lg:col-span-2 space-y-6">
                    {/* Title */}
                    <div className="space-y-2">
                        <Label htmlFor="title">Title *</Label>
                        <Input
                            id="title"
                            value={formData.title}
                            onChange={(e) => handleTitleChange(e.target.value)}
                            placeholder="Enter post title..."
                            className={errors.title ? 'border-red-500' : ''}
                        />
                        {errors.title && <p className="text-sm text-red-500">{errors.title}</p>}
                    </div>

                    {/* Slug */}
                    <div className="space-y-2">
                        <Label htmlFor="slug">Slug *</Label>
                        <Input
                            id="slug"
                            value={formData.slug}
                            onChange={(e) => handleSlugChange(e.target.value)}
                            placeholder="post-url-slug"
                            className={errors.slug ? 'border-red-500' : ''}
                        />
                        {errors.slug && <p className="text-sm text-red-500">{errors.slug}</p>}
                    </div>

                    {/* Excerpt */}
                    <div className="space-y-2">
                        <Label htmlFor="excerpt">Excerpt *</Label>
                        <Textarea
                            id="excerpt"
                            value={formData.excerpt}
                            onChange={(e) => {
                                setFormData(prev => ({ ...prev, excerpt: e.target.value }))
                                if (errors.excerpt) setErrors(prev => ({ ...prev, excerpt: '' }))
                            }}
                            placeholder="Brief description of the post..."
                            rows={3}
                            className={errors.excerpt ? 'border-red-500' : ''}
                        />
                        {errors.excerpt && <p className="text-sm text-red-500">{errors.excerpt}</p>}
                    </div>

                    {/* Content */}
                    <div className="space-y-2">
                        <Label htmlFor="content">Content *</Label>
                        <Textarea
                            id="content"
                            value={formData.content}
                            onChange={(e) => {
                                setFormData(prev => ({ ...prev, content: e.target.value }))
                                if (errors.content) setErrors(prev => ({ ...prev, content: '' }))
                            }}
                            placeholder="Write your blog content here (HTML or Markdown supported)..."
                            rows={20}
                            className={errors.content ? 'border-red-500' : ''}
                        />
                        {errors.content && <p className="text-sm text-red-500">{errors.content}</p>}
                    </div>

                    {/* Cover Image Upload */}
                    <div className="space-y-2">
                        <Label>Cover Image *</Label>
                        {formData.coverImage ? (
                            <div className="relative w-full h-48 rounded-lg overflow-hidden bg-muted">
                                <Image
                                    src={formData.coverImage}
                                    alt="Cover"
                                    fill
                                    className="object-cover"
                                />
                                <Button
                                    variant="destructive"
                                    size="sm"
                                    className="absolute top-2 right-2"
                                    onClick={() => setFormData(prev => ({ ...prev, coverImage: '' }))}
                                >
                                    Remove
                                </Button>
                            </div>
                        ) : (
                            <div className="border-2 border-dashed border-border rounded-lg p-8 text-center">
                                <Upload className="h-12 w-12 mx-auto mb-4 text-muted-foreground" />
                                <p className="text-sm text-medium-gray mb-4">
                                    Click to upload or drag and drop
                                </p>
                                <input
                                    type="file"
                                    accept="image/*"
                                    onChange={(e) => {
                                        const file = e.target.files?.[0]
                                        if (file) handleCloudinaryUpload(file)
                                    }}
                                    className="hidden"
                                    id="cover-upload"
                                />
                                <label htmlFor="cover-upload">
                                    <Button variant="outline" disabled={uploading} asChild>
                                        <span>
                                            {uploading ? 'Uploading...' : 'Choose File'}
                                        </span>
                                    </Button>
                                </label>
                            </div>
                        )}
                        {errors.coverImage && <p className="text-sm text-red-500">{errors.coverImage}</p>}
                    </div>
                </div>

                {/* Sidebar */}
                <div className="space-y-6">
                    {/* Category */}
                    <Card>
                        <CardHeader>
                            <CardTitle className="text-lg">Category</CardTitle>
                            <CardDescription>Choose a category for this post</CardDescription>
                        </CardHeader>
                        <CardContent>
                            <Select value={formData.category} onValueChange={(value) => setFormData(prev => ({ ...prev, category: value }))}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Select category" />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="">No category</SelectItem>
                                    <SelectItem value="Travel Tips">Travel Tips</SelectItem>
                                    <SelectItem value="Culture">Culture</SelectItem>
                                    <SelectItem value="Food">Food</SelectItem>
                                    <SelectItem value="Guides">Guides</SelectItem>
                                    <SelectItem value="Events">Events</SelectItem>
                                </SelectContent>
                            </Select>
                        </CardContent>
                    </Card>

                    {/* Featured */}
                    <Card>
                        <CardHeader>
                            <CardTitle className="text-lg">Featured Post</CardTitle>
                            <CardDescription>Mark this post as featured</CardDescription>
                        </CardHeader>
                        <CardContent>
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="font-medium">Featured</p>
                                    <p className="text-sm text-medium-gray">Show on homepage</p>
                                </div>
                                <Switch
                                    checked={formData.featured}
                                    onCheckedChange={(checked) => setFormData(prev => ({ ...prev, featured: checked }))}
                                />
                            </div>
                        </CardContent>
                    </Card>

                    {/* SEO */}
                    <Card>
                        <CardHeader>
                            <CardTitle className="text-lg">SEO</CardTitle>
                            <CardDescription>Search engine optimization</CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <div>
                                <Label htmlFor="metaTitle">Meta Title</Label>
                                <Input
                                    id="metaTitle"
                                    value={formData.metaTitle}
                                    onChange={(e) => setFormData(prev => ({ ...prev, metaTitle: e.target.value }))}
                                    placeholder="SEO title (optional)"
                                />
                            </div>
                            <div>
                                <Label htmlFor="metaDescription">Meta Description</Label>
                                <Textarea
                                    id="metaDescription"
                                    value={formData.metaDescription}
                                    onChange={(e) => setFormData(prev => ({ ...prev, metaDescription: e.target.value }))}
                                    placeholder="SEO description (optional)"
                                    rows={2}
                                />
                            </div>
                            <div>
                                <Label>Keywords</Label>
                                <div className="flex flex-wrap gap-2 mt-2">
                                    {formData.keywords.map((keyword, index) => (
                                        <Badge key={index} variant="secondary" className="cursor-pointer" onClick={() => handleKeywordRemove(index)}>
                                            {keyword} ├ù
                                        </Badge>
                                    ))}
                                </div>
                                <Input
                                    placeholder="Add keyword and press Enter"
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') {
                                            e.preventDefault()
                                            handleKeywordAdd((e.target as HTMLInputElement).value)
                                            ;(e.target as HTMLInputElement).value = ''
                                        }
                                    }}
                                    className="mt-2"
                                />
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </div>
        </div>
    )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { Booking } from '@prisma/client'
import { confirmBooking, cancelBooking, processBooking, deleteBooking } from '@/app/actions/booking-actions'
import { toast } from 'sonner'
import { format } from 'date-fns'
import {
    Search,
    Calendar,
    CheckCircle,
    XCircle,
    CheckCircle2,
    Trash2,
    ArrowUpDown,
    Phone,
    Mail,
    Users,
    Filter,
    MoreHorizontal,
    Eye
} from 'lucide-react'
import { Card, CardContent } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { BookingStatusBadge, PaymentStatusBadge } from '@/components/ui/status-badge'
import { EmptyState } from '@/components/ui/empty-state'

interface BookingsClientProps {
    initialBookings: (Booking & { service?: { title: string } })[]
}

export default function BookingsClient({ initialBookings }: BookingsClientProps) {
    const router = useRouter()
    const [bookings, setBookings] = useState<(Booking & { service?: { title: string } })[]>(initialBookings)
    const [searchQuery, setSearchQuery] = useState('')
    const [statusFilter, setStatusFilter] = useState<string>('ALL')
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc')
    const [isPending, startTransition] = useTransition()

    // Filter and Sort
    const filteredBookings = bookings
        .filter((booking) => {
            // Status filter
            if (statusFilter !== 'ALL' && booking.status !== statusFilter) {
                return false
            }

            // Search filter
            const query = searchQuery.toLowerCase()
            return (
                (booking.name || '').toLowerCase().includes(query) ||
                (booking.email || '').toLowerCase().includes(query) ||
                (booking.service?.title || booking.activityTitle || '').toLowerCase().includes(query)
            )
        })
        .sort((a, b) => {
            const dateA = new Date(a.date).getTime()
            const dateB = new Date(b.date).getTime()
            return sortOrder === 'asc' ? dateA - dateB : dateB - dateA
        })

    const handleConfirm = async (id: string) => {
        startTransition(async () => {
            const result = await confirmBooking(id)
            if (result.success) {
                toast.success('Booking confirmed successfully')
                setBookings((prev) =>
                    prev.map((b) => b.id === id ? { ...b, status: 'CONFIRMED' } : b)
                )
            } else {
                toast.error('Failed to confirm booking')
            }
        })
    }

    const handleCancel = async (id: string) => {
        if (!confirm('Are you sure you want to cancel this booking?')) return

        startTransition(async () => {
            const result = await cancelBooking(id)
            if (result.success) {
                toast.success('Booking cancelled successfully')
                setBookings((prev) =>
                    prev.map((b) => b.id === id ? { ...b, status: 'CANCELLED' } : b)
                )
            } else {
                toast.error('Failed to cancel booking')
            }
        })
    }

    const handleProcess = async (id: string) => {
        if (!confirm('Mark this booking as completed? This action cannot be undone.')) return

        startTransition(async () => {
            const result = await processBooking(id)
            if (result.success) {
                toast.success('Booking marked as completed')
                setBookings((prev) =>
                    prev.map((b) => b.id === id ? { ...b, status: 'COMPLETED' } : b)
                )
            } else {
                toast.error('Failed to process booking')
            }
        })
    }

    const handleDelete = async (id: string) => {
        if (!confirm('Are you sure you want to delete this booking? This action cannot be undone.')) return

        startTransition(async () => {
            const result = await deleteBooking(id)
            if (result.success) {
                toast.success('Booking deleted successfully')
                setBookings((prev) => prev.filter((b) => b.id !== id))
            } else {
                toast.error('Failed to delete booking')
            }
        })
    }

    const toggleSort = () => {
        setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')
    }

    const handleViewDetails = (booking: Booking & { service?: { title: string } }) => {
        // Navigate to client booking details page (admin can view client bookings)
        router.push(`/client/bookings/${booking.id}`)
    }

    return (
        <div className="space-y-6">
            {/* Controls */}
            <div className="flex flex-col gap-4 bg-white p-4 sm:p-5 rounded-xl shadow-sm border border-border">
                <div className="flex flex-col sm:flex-row gap-3 justify-between items-stretch sm:items-center">
                    <div className="relative flex-1 max-w-md">
                        <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-muted-foreground h-4 w-4" />
                        <input
                            type="text"
                            placeholder="Search by name, email, or activity..."
                            className="w-full pl-10 pr-4 py-2.5 border-2 border-border rounded-xl bg-white text-sm focus:outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 transition-all duration-200"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>

                    <Button
                        variant="outline"
                        onClick={toggleSort}
                        className="flex items-center gap-2 rounded-xl border-2"
                    >
                        <ArrowUpDown className="h-4 w-4" />
                        <span className="hidden sm:inline">Sort:</span> {sortOrder === 'asc' ? 'Oldest' : 'Newest'}
                    </Button>
                </div>

                {/* Status Filter */}
                <div className="flex items-center gap-2 flex-wrap">
                    <div className="flex items-center gap-1.5 text-sm font-medium text-muted-foreground mr-2">
                        <Filter className="h-4 w-4" />
                        <span className="hidden sm:inline">Status:</span>
                    </div>
                    {['ALL', 'PENDING', 'CONFIRMED', 'COMPLETED', 'CANCELLED'].map((status) => (
                        <button
                            key={status}
                            onClick={() => setStatusFilter(status)}
                            className={`px-3 py-1.5 text-xs sm:text-sm font-medium rounded-full transition-all duration-200 ${statusFilter === status
                                    ? 'bg-primary text-white shadow-md shadow-primary/25'
                                    : 'bg-muted text-muted-foreground hover:bg-muted/80 hover:text-foreground'
                                }`}
                        >
                            {status === 'ALL' ? 'All' : status.charAt(0) + status.slice(1).toLowerCase()}
                        </button>
                    ))}
                </div>
            </div>

            {/* Mobile Card View */}
            <div className="block md:hidden space-y-3">
                {filteredBookings && filteredBookings.length > 0 ? (
                    filteredBookings.map((booking) => (
                        <Card key={booking.id} className="overflow-hidden rounded-xl border-border hover:shadow-md transition-all duration-200">
                            <CardContent className="p-0 flex h-full">
                                {/* Left Side - Date & Status */}
                                <div className={`w-20 flex-shrink-0 flex flex-col items-center justify-center p-3 text-white ${
                                    booking.status === 'CONFIRMED' ? 'bg-gradient-to-b from-emerald-500 to-emerald-600' :
                                    booking.status === 'CANCELLED' ? 'bg-gradient-to-b from-red-500 to-red-600' :
                                    booking.status === 'COMPLETED' ? 'bg-gradient-to-b from-blue-500 to-blue-600' : 
                                    'bg-gradient-to-b from-amber-500 to-amber-600'
                                }`}>
                                    <div className="text-center">
                                        <div className="font-bold text-2xl">{new Date(booking.date).getDate()}</div>
                                        <div className="text-xs uppercase font-medium opacity-90">{format(new Date(booking.date), 'MMM')}</div>
                                        <div className="mt-2 text-[10px] font-semibold uppercase tracking-wider bg-white/20 px-2 py-0.5 rounded">
                                            {booking.status.slice(0, 4)}
                                        </div>
                                    </div>
                                </div>

                                {/* Right Side Content */}
                                <div className="flex-1 p-3 flex flex-col justify-between min-w-0">
                                    <div className="flex justify-between items-start gap-2">
                                        <div className="min-w-0">
                                            <h3 className="font-semibold text-sm text-foreground truncate leading-tight">
                                                {booking.activityTitle || booking.service?.title}
                                            </h3>
                                            <p className="text-xs text-muted-foreground truncate mt-0.5">{booking.name}</p>
                                        </div>
                                        <div className="flex flex-col items-end shrink-0">
                                            <span className="font-bold text-primary text-base">Γé¼{booking.totalPrice.toFixed(0)}</span>
                                            <PaymentStatusBadge status={booking.paymentStatus} />
                                        </div>
                                    </div>

                                    <div className="flex justify-between items-end mt-3">
                                        <div className="flex items-center gap-3">
                                            <div className="flex items-center gap-1.5 text-xs text-muted-foreground bg-muted px-2 py-1 rounded-md">
                                                <Users className="h-3 w-3" />
                                                <span>{booking.guests}</span>
                                            </div>
                                            {booking.phone && (
                                                <div className="flex items-center gap-1.5 text-xs text-muted-foreground bg-muted px-2 py-1 rounded-md">
                                                    <Phone className="h-3 w-3" />
                                                </div>
                                            )}
                                        </div>

                                        <div className="flex gap-1.5">
                                            {booking.status === 'PENDING' && (
                                                <Button size="icon" className="h-8 w-8 rounded-lg bg-emerald-100 text-emerald-700 hover:bg-emerald-200 shadow-sm" onClick={(e) => { e.stopPropagation(); handleConfirm(booking.id); }} disabled={isPending}>
                                                    <CheckCircle className="h-4 w-4" />
                                                </Button>
                                            )}
                                            {(booking.status === 'PENDING' || booking.status === 'CONFIRMED') && (
                                                <Button size="icon" className="h-8 w-8 rounded-lg bg-red-100 text-red-700 hover:bg-red-200 shadow-sm" onClick={(e) => { e.stopPropagation(); handleCancel(booking.id); }} disabled={isPending}>
                                                    <XCircle className="h-4 w-4" />
                                                </Button>
                                            )}
                                            <Button size="icon" variant="outline" className="h-8 w-8 rounded-lg" onClick={() => handleViewDetails(booking)}>
                                                <Eye className="h-4 w-4" />
                                            </Button>
                                        </div>
                                    </div>
                                </div>
                            </CardContent>
                        </Card>
                    ))
                ) : (
                    <EmptyState
                        icon="bookings"
                        title="No bookings found"
                        description={searchQuery ? `No results for "${searchQuery}"` : "Bookings will appear here when customers make reservations."}
                        compact
                    />
                )}
            </div>

            {/* Desktop Table View */}
            <div className="hidden md:block bg-white rounded-xl shadow-sm border border-border overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-muted/50 border-b border-border">
                            <tr>
                                <th className="px-5 py-4 font-semibold text-foreground text-xs uppercase tracking-wider">Guest</th>
                                <th className="px-5 py-4 font-semibold text-foreground text-xs uppercase tracking-wider">Contact</th>
                                <th className="px-5 py-4 font-semibold text-foreground text-xs uppercase tracking-wider">Activity</th>
                                <th className="px-5 py-4 font-semibold text-foreground text-xs uppercase tracking-wider">Date & Guests</th>
                                <th className="px-5 py-4 font-semibold text-foreground text-xs uppercase tracking-wider">Total</th>
                                <th className="px-5 py-4 font-semibold text-foreground text-xs uppercase tracking-wider">Status</th>
                                <th className="px-5 py-4 font-semibold text-foreground text-xs uppercase tracking-wider text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {filteredBookings.length === 0 ? (
                                <tr>
                                    <td colSpan={7} className="px-6 py-16">
                                        <EmptyState
                                            icon="bookings"
                                            title="No bookings found"
                                            description={searchQuery ? `No results for "${searchQuery}"` : "Bookings will appear here when customers make reservations."}
                                            compact
                                        />
                                    </td>
                                </tr>
                            ) : (
                                filteredBookings.map((booking) => (
                                    <tr key={booking.id} className="hover:bg-muted/30 transition-colors">
                                        <td className="px-5 py-4">
                                            <div className="flex items-center gap-3">
                                                <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
                                                    <span className="text-primary font-semibold text-sm">
                                                        {booking.name?.charAt(0)?.toUpperCase() || '?'}
                                                    </span>
                                                </div>
                                                <div>
                                                    <div className="font-medium text-foreground">{booking.name}</div>
                                                    <div className="text-xs text-muted-foreground font-mono">#{booking.id.slice(-6)}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-5 py-4">
                                            <div className="flex items-center gap-2 text-muted-foreground text-sm">
                                                <Mail className="h-3.5 w-3.5 shrink-0" />
                                                <span className="truncate max-w-[150px]">{booking.email}</span>
                                            </div>
                                            {booking.phone && (
                                                <div className="flex items-center gap-2 text-muted-foreground text-sm mt-1">
                                                    <Phone className="h-3.5 w-3.5 shrink-0" />
                                                    {booking.phone}
                                                </div>
                                            )}
                                        </td>
                                        <td className="px-5 py-4">
                                            <div className="font-medium text-foreground max-w-[200px] truncate">{booking.activityTitle || booking.service?.title}</div>
                                        </td>
                                        <td className="px-5 py-4">
                                            <div className="flex items-center gap-2 text-foreground">
                                                <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
                                                {format(new Date(booking.date), 'MMM d, yyyy')}
                                            </div>
                                            <div className="flex items-center gap-2 text-muted-foreground text-sm mt-1">
                                                <Users className="h-3.5 w-3.5" />
                                                {booking.guests} guest{booking.guests !== 1 && 's'}
                                            </div>
                                        </td>
                                        <td className="px-5 py-4">
                                            <div className="font-bold text-foreground text-base">
                                                Γé¼{booking.totalPrice.toFixed(0)}
                                            </div>
                                            <PaymentStatusBadge status={booking.paymentStatus} />
                                        </td>
                                        <td className="px-5 py-4">
                                            <BookingStatusBadge status={booking.status} />
                                        </td>
                                        <td className="px-5 py-4 text-right">
                                            <div className="flex items-center justify-end gap-1">
                                                {booking.status === 'PENDING' && (
                                                    <Button
                                                        size="icon"
                                                        variant="ghost"
                                                        onClick={() => handleConfirm(booking.id)}
                                                        disabled={isPending}
                                                        className="h-8 w-8 rounded-lg text-emerald-600 hover:bg-emerald-50 hover:text-emerald-700"
                                                        title="Confirm Booking"
                                                    >
                                                        <CheckCircle className="h-4 w-4" />
                                                    </Button>
                                                )}

                                                {(booking.status === 'PENDING' || booking.status === 'CONFIRMED') && (
                                                    <Button
                                                        size="icon"
                                                        variant="ghost"
                                                        onClick={() => handleCancel(booking.id)}
                                                        disabled={isPending}
                                                        className="h-8 w-8 rounded-lg text-amber-600 hover:bg-amber-50 hover:text-amber-700"
                                                        title="Cancel Booking"
                                                    >
                                                        <XCircle className="h-4 w-4" />
                                                    </Button>
                                                )}

                                                {booking.status === 'CONFIRMED' && (
                                                    <Button
                                                        size="icon"
                                                        variant="ghost"
                                                        onClick={() => handleProcess(booking.id)}
                                                        disabled={isPending}
                                                        className="h-8 w-8 rounded-lg text-blue-600 hover:bg-blue-50 hover:text-blue-700"
                                                        title="Mark as Completed"
                                                    >
                                                        <CheckCircle2 className="h-4 w-4" />
                                                    </Button>
                                                )}

                                                <Button
                                                    size="icon"
                                                    variant="ghost"
                                                    onClick={() => handleDelete(booking.id)}
                                                    disabled={isPending}
                                                    className="h-8 w-8 rounded-lg text-red-600 hover:bg-red-50 hover:text-red-700"
                                                    title="Delete Booking"
                                                >
                                                    <Trash2 className="h-4 w-4" />
                                                </Button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    )
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Mail, Phone, Calendar, Trash2, RefreshCw } from "lucide-react";
import { toast } from "sonner";
import { format } from "date-fns";

interface SupportRequest {
    id: string;
    name: string;
    email: string;
    phone: string | null;
    subject: string;
    message: string;
    status: string;
    createdAt: string;
    updatedAt: string;
}

export default function ComplaintsPage() {
    const [requests, setRequests] = useState<SupportRequest[]>([]);
    const [loading, setLoading] = useState(true);
    const [statusFilter, setStatusFilter] = useState("ALL");
    const [deleteId, setDeleteId] = useState<string | null>(null);

    const fetchRequests = async () => {
        try {
            setLoading(true);
            const url = statusFilter === "ALL"
                ? "/api/admin/support-requests"
                : `/api/admin/support-requests?status=${statusFilter}`;

            const response = await fetch(url);
            if (!response.ok) throw new Error("Failed to fetch");

            const data = await response.json();
            setRequests(data);
        } catch (error) {
            toast.error("Failed to load support requests");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchRequests();
    }, [statusFilter]);

    const updateStatus = async (id: string, newStatus: string) => {
        try {
            const response = await fetch(`/api/admin/support-requests/${id}`, {
                method: "PATCH",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ status: newStatus }),
            });

            if (!response.ok) throw new Error("Failed to update");

            toast.success("Status updated successfully");
            fetchRequests();
        } catch (error) {
            toast.error("Failed to update status");
        }
    };

    const deleteRequest = async (id: string) => {
        try {
            const response = await fetch(`/api/admin/support-requests/${id}`, {
                method: "DELETE",
            });

            if (!response.ok) throw new Error("Failed to delete");

            toast.success("Request deleted successfully");
            setDeleteId(null);
            fetchRequests();
        } catch (error) {
            toast.error("Failed to delete request");
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case "PENDING":
                return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400";
            case "IN_PROGRESS":
                return "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400";
            case "RESOLVED":
                return "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400";
            default:
                return "bg-gray-100 text-gray-800";
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Support Requests</h1>
                    <p className="text-muted-foreground mt-1">
                        Manage customer support requests and complaints
                    </p>
                </div>
                <div className="flex items-center gap-3">
                    <Select value={statusFilter} onValueChange={setStatusFilter}>
                        <SelectTrigger className="w-[180px]">
                            <SelectValue placeholder="Filter by status" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="ALL">All Requests</SelectItem>
                            <SelectItem value="PENDING">Pending</SelectItem>
                            <SelectItem value="IN_PROGRESS">In Progress</SelectItem>
                            <SelectItem value="RESOLVED">Resolved</SelectItem>
                        </SelectContent>
                    </Select>
                    <Button onClick={fetchRequests} variant="outline" size="icon">
                        <RefreshCw className="h-4 w-4" />
                    </Button>
                </div>
            </div>

            {loading ? (
                <div className="flex justify-center items-center py-12">
                    <RefreshCw className="h-8 w-8 animate-spin text-primary" />
                </div>
            ) : requests.length === 0 ? (
                <Card>
                    <CardContent className="py-12 text-center">
                        <p className="text-muted-foreground">No support requests found</p>
                    </CardContent>
                </Card>
            ) : (
                <div className="grid gap-6">
                    {requests.map((request) => (
                        <Card key={request.id} className="hover:shadow-md transition-shadow">
                            <CardHeader className="pb-3">
                                <div className="flex flex-col sm:flex-row justify-between items-start gap-3">
                                    <div className="flex-1">
                                        <CardTitle className="text-xl mb-2">{request.subject}</CardTitle>
                                        <div className="flex flex-wrap items-center gap-3 text-sm text-muted-foreground">
                                            <div className="flex items-center gap-1.5">
                                                <Mail className="h-4 w-4" />
                                                <span>{request.email}</span>
                                            </div>
                                            {request.phone && (
                                                <div className="flex items-center gap-1.5">
                                                    <Phone className="h-4 w-4" />
                                                    <span>{request.phone}</span>
                                                </div>
                                            )}
                                            <div className="flex items-center gap-1.5">
                                                <Calendar className="h-4 w-4" />
                                                <span>{format(new Date(request.createdAt), "MMM dd, yyyy")}</span>
                                            </div>
                                        </div>
                                    </div>
                                    <Badge className={getStatusColor(request.status)}>
                                        {request.status.replace("_", " ")}
                                    </Badge>
                                </div>
                            </CardHeader>
                            <CardContent className="space-y-4">
                                <div>
                                    <p className="text-sm font-medium mb-1">From: {request.name}</p>
                                    <p className="text-sm text-muted-foreground whitespace-pre-wrap">
                                        {request.message}
                                    </p>
                                </div>
                                <div className="flex flex-wrap gap-2 pt-2 border-t">
                                    <Select
                                        value={request.status}
                                        onValueChange={(value) => updateStatus(request.id, value)}
                                    >
                                        <SelectTrigger className="w-[160px]">
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="PENDING">Pending</SelectItem>
                                            <SelectItem value="IN_PROGRESS">In Progress</SelectItem>
                                            <SelectItem value="RESOLVED">Resolved</SelectItem>
                                        </SelectContent>
                                    </Select>
                                    <Button
                                        variant="destructive"
                                        size="sm"
                                        onClick={() => setDeleteId(request.id)}
                                    >
                                        <Trash2 className="h-4 w-4 mr-2" />
                                        Delete
                                    </Button>
                                </div>
                            </CardContent>
                        </Card>
                    ))}
                </div>
            )}

            <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Are you sure?</AlertDialogTitle>
                        <AlertDialogDescription>
                            This action cannot be undone. This will permanently delete the support request.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>Cancel</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={() => deleteId && deleteRequest(deleteId)}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                        >
                            Delete
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { CalendarDays, CreditCard, TrendingUp, Users, ArrowUpRight, ArrowDownRight, Sparkles } from "lucide-react";
import Link from "next/link";
import { Badge } from "@/components/ui/badge";
import { BookingStatusBadge } from "@/components/ui/status-badge";
import { format } from "date-fns";
import { adminService } from "@/services/admin.service";

export const dynamic = 'force-dynamic';

async function getData() {
    const stats = await adminService.getDashboardStats();

    return {
        stats: {
            bookingsCount: stats.overview.totalBookings,
            usersCount: stats.users.total,
            servicesCount: stats.overview.totalServices,
            totalRevenue: stats.revenue.total
        },
        recentBookings: stats.recent.bookings
    };
}

export default async function AdminDashboard() {
    const { stats, recentBookings } = await getData();

    return (
        <div className="space-y-8">
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                <div>
                    <h1 className="text-2xl sm:text-3xl font-bold tracking-tight text-foreground">Dashboard</h1>
                    <p className="text-muted-foreground text-sm sm:text-base">Welcome back! Here's your platform overview.</p>
                </div>
                <div className="flex items-center gap-2 text-sm text-muted-foreground bg-muted/50 px-3 py-1.5 rounded-full">
                    <Sparkles className="h-4 w-4 text-primary" />
                    <span>Live data</span>
                </div>
            </div>

            {/* Stats Grid */}
            <div className="grid gap-4 grid-cols-2 lg:grid-cols-4">
                <StatsCard
                    title="Total Revenue"
                    value={`Γé¼${stats.totalRevenue.toLocaleString()}`}
                    icon={CreditCard}
                    description="Lifetime volume"
                    trend={{ value: 12.5, isPositive: true }}
                    gradient="from-emerald-500 to-teal-600"
                />
                <StatsCard
                    title="Total Bookings"
                    value={stats.bookingsCount.toString()}
                    icon={CalendarDays}
                    description="All time"
                    trend={{ value: 8.2, isPositive: true }}
                    gradient="from-primary to-accent"
                />
                <StatsCard
                    title="Total Users"
                    value={stats.usersCount.toString()}
                    icon={Users}
                    description="Registered accounts"
                    trend={{ value: 5.1, isPositive: true }}
                    gradient="from-blue-500 to-indigo-600"
                />
                <StatsCard
                    title="Experiences"
                    value={stats.servicesCount.toString()}
                    icon={TrendingUp}
                    description="Active listings"
                    gradient="from-purple-500 to-pink-600"
                />
            </div>

            {/* Recent Bookings and Activity */}
            <div className="grid gap-6 lg:grid-cols-7">
                <Card className="lg:col-span-4 rounded-xl border-border shadow-sm hover:shadow-md transition-shadow">
                    <CardHeader className="flex flex-row items-center justify-between">
                        <CardTitle className="text-lg font-semibold">Recent Bookings</CardTitle>
                        <Link href="/admin/bookings" className="text-sm text-primary hover:underline font-medium">
                            View all ΓåÆ
                        </Link>
                    </CardHeader>
                    <CardContent>
                        <div className="space-y-3">
                            {recentBookings.length === 0 ? (
                                <div className="text-center py-8">
                                    <CalendarDays className="h-12 w-12 text-muted-foreground/30 mx-auto mb-3" />
                                    <p className="text-sm text-muted-foreground">No bookings yet</p>
                                </div>
                            ) : (
                                recentBookings.map((booking) => (
                                    <div key={booking.id} className="flex items-center justify-between p-3 rounded-xl bg-muted/30 hover:bg-muted/50 transition-colors">
                                        <div className="flex items-center gap-3 min-w-0">
                                            <div className="h-10 w-10 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
                                                <CalendarDays className="h-5 w-5 text-primary" />
                                            </div>
                                            <div className="min-w-0">
                                                <p className="text-sm font-medium text-foreground truncate">
                                                    {booking.user?.name || booking.name}
                                                </p>
                                                <p className="text-xs text-muted-foreground truncate">{booking.activityTitle}</p>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-3 shrink-0">
                                            <div className="text-right hidden sm:block">
                                                <p className="font-semibold text-foreground">Γé¼{booking.totalPrice}</p>
                                            </div>
                                            <BookingStatusBadge status={booking.status} />
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </CardContent>
                </Card>

                <Card className="lg:col-span-3 rounded-xl border-border shadow-sm">
                    <CardHeader>
                        <CardTitle className="text-lg font-semibold">System Health</CardTitle>
                    </CardHeader>
                    <CardContent>
                        <div className="space-y-4">
                            <HealthItem status="operational" title="Database" description="Connected & responsive" />
                            <HealthItem status="operational" title="API Gateway" description="All endpoints active" />
                            <HealthItem status="operational" title="Email Service" description="Sending normally" />
                            <HealthItem status="operational" title="Payment System" description="Ready for transactions" />
                        </div>
                    </CardContent>
                </Card>
            </div>
        </div>
    );
}

function HealthItem({ status, title, description }: { status: 'operational' | 'degraded' | 'down'; title: string; description: string }) {
    const statusStyles = {
        operational: 'bg-emerald-500',
        degraded: 'bg-amber-500',
        down: 'bg-red-500'
    };

    return (
        <div className="flex items-center gap-3 p-2 rounded-lg hover:bg-muted/50 transition-colors">
            <div className="relative">
                <div className={`h-2.5 w-2.5 rounded-full ${statusStyles[status]}`} />
                <div className={`absolute inset-0 h-2.5 w-2.5 rounded-full ${statusStyles[status]} animate-ping opacity-75`} />
            </div>
            <div className="flex-1">
                <p className="text-sm font-medium text-foreground">{title}</p>
                <p className="text-xs text-muted-foreground">{description}</p>
            </div>
        </div>
    );
}

interface StatsCardProps {
    title: string;
    value: string;
    icon: React.ComponentType<{ className?: string }>;
    description: string;
    trend?: { value: number; isPositive: boolean };
    gradient: string;
}

function StatsCard({ title, value, icon: Icon, description, trend, gradient }: StatsCardProps) {
    return (
        <Card className="relative overflow-hidden rounded-xl border-border hover:shadow-lg transition-all duration-300 hover:-translate-y-1">
            <div className={`absolute top-0 right-0 w-24 h-24 bg-gradient-to-br ${gradient} opacity-10 rounded-bl-full`} />
            <CardHeader className="flex flex-row items-start justify-between space-y-0 pb-2">
                <div className={`h-10 w-10 rounded-xl bg-gradient-to-br ${gradient} flex items-center justify-center shadow-lg`}>
                    <Icon className="h-5 w-5 text-white" />
                </div>
                {trend && (
                    <div className={`flex items-center gap-1 text-xs font-medium px-2 py-1 rounded-full ${
                        trend.isPositive ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'
                    }`}>
                        {trend.isPositive ? <ArrowUpRight className="h-3 w-3" /> : <ArrowDownRight className="h-3 w-3" />}
                        {trend.value}%
                    </div>
                )}
            </CardHeader>
            <CardContent className="pt-2">
                <p className="text-xs text-muted-foreground font-medium uppercase tracking-wide">{title}</p>
                <div className="text-2xl sm:text-3xl font-bold text-foreground mt-1">{value}</div>
                <p className="text-xs text-muted-foreground mt-1">{description}</p>
            </CardContent>
        </Card>
    );
}

import { AdminSidebar } from "@/components/admin/AdminSidebar";
import { AdminHeader } from "@/components/admin/AdminHeader";
import { requireAdmin } from "@/lib/authorization";
import { redirect } from "next/navigation";

export default async function AdminLayout({ children }: { children: React.ReactNode }) {
    try {
        await requireAdmin();
    } catch (error) {
        redirect("/admin/login");
    }

    return (
        <div className="flex min-h-screen bg-muted/20">
            {/* Desktop Sidebar (hidden on mobile) */}
            <div className="hidden md:block w-64 border-r bg-white fixed h-full inset-y-0 z-50">
                <AdminSidebar />
            </div>

            {/* Main Content Area */}
            <div className="flex-1 flex flex-col md:pl-64">
