    );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { format } from "date-fns";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Loader2, Send, MessageSquare, ArrowLeft, XCircle, Trash2, CheckCircle } from "lucide-react";
import { cn } from "@/lib/utils";

interface ConversationSummary {
    id: string;
    subject: string;
    status: string;
    updatedAt: string;
    lastMessage: string;
    lastMessageTime: string;
    userName: string;
    userEmail: string;
    unreadCount: number;
    userId: string;
}

interface MessageData {
    id: string;
    content: string;
    sender: string;
    createdAt: string;
}

export default function AdminMessagesPage() {
    const router = useRouter();
    const [conversations, setConversations] = useState<ConversationSummary[]>([]);
    const [selectedConversation, setSelectedConversation] = useState<ConversationSummary | null>(null);
    const [messages, setMessages] = useState<MessageData[]>([]);
    const [newMessage, setNewMessage] = useState("");
    const [isLoading, setIsLoading] = useState(true);
    const [sending, setSending] = useState(false);

    useEffect(() => {
        fetch('/api/auth/me')
            .then(res => res.json())
            .then(data => {
                if (!data.user || data.user.role !== 'ADMIN') {
                    router.push('/admin');
                } else {
                    fetchConversations();
                }
            });
    }, [router]);

    useEffect(() => {
        if (selectedConversation) {
            const interval = setInterval(() => {
                fetchMessages(selectedConversation.id);
                fetchConversations(); // Refresh to get updated status
            }, 3000);
            return () => clearInterval(interval);
        }
    }, [selectedConversation]);

    const fetchConversations = async () => {
        try {
            const res = await fetch('/api/admin/conversations');
            if (res.ok) {
                const data = await res.json();
                setConversations(data);
            }
        } catch (error) {
            console.error(error);
        } finally {
            setIsLoading(false);
        }
    };

    const fetchMessages = async (conversationId: string) => {
        try {
            const res = await fetch(`/api/admin/messages/${conversationId}`);
            if (res.ok) {
                setMessages(await res.json());
            }
        } catch (error) {
            console.error(error);
        }
    };

    const handleSelectConversation = (conv: ConversationSummary) => {
        setSelectedConversation(conv);
        fetchMessages(conv.id);
    };

    const handleCloseConversation = async () => {
        if (!selectedConversation || !confirm('Close this conversation? The user will no longer be able to send messages to this ticket.')) return;

        try {
            const res = await fetch(`/api/admin/conversations/${selectedConversation.id}/close`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'close' })
            });

            if (res.ok) {
                toast.success("Conversation closed");
                fetchConversations();
                fetchMessages(selectedConversation.id);
            } else {
                const errorData = await res.json();
                console.error('Close error:', errorData);
                toast.error(errorData.details || errorData.error || "Failed to close conversation");
            }
        } catch (error) {
            console.error('Close exception:', error);
            toast.error("Failed to close conversation");
        }
    };

    const handleReopenConversation = async () => {
        if (!selectedConversation || !confirm('Reopen this conversation? The user will be able to send messages again.')) return;

        try {
            const res = await fetch(`/api/admin/conversations/${selectedConversation.id}/close`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'reopen' })
            });

            if (res.ok) {
                toast.success("Conversation reopened");
                fetchConversations();
                fetchMessages(selectedConversation.id);
            } else {
                const errorData = await res.json();
                toast.error(errorData.details || errorData.error || "Failed to reopen conversation");
            }
        } catch (error) {
            toast.error("Failed to reopen conversation");
        }
    };

    const handleDeleteConversation = async () => {
        if (!selectedConversation || !confirm('Delete this entire conversation? This action cannot be undone.')) return;

        try {
            const res = await fetch(`/api/admin/conversations/${selectedConversation.userId}`, {
                method: 'DELETE'
            });

            if (res.ok) {
                toast.success("Conversation deleted");
                setSelectedConversation(null);
                fetchConversations();
            } else {
                toast.error("Failed to delete conversation");
            }
        } catch (error) {
            toast.error("Failed to delete conversation");
        }
    };

    const handleSendMessage = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newMessage.trim() || !selectedConversation) return;

        setSending(true);
        try {
            const res = await fetch(`/api/admin/messages/${selectedConversation.id}`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ content: newMessage })
            });

            if (res.ok) {
                const msg = await res.json();
                setMessages([...messages, msg]);
                setNewMessage("");
            } else {
                toast.error("Failed to send message");
            }
        } finally {
            setSending(false);
        }
    };

    if (isLoading) {
        return <div className="flex h-screen items-center justify-center"><Loader2 className="animate-spin" /></div>;
    }

    return (
        <div className="container mx-auto p-6">
            <div className="mb-6 flex items-center gap-4">
                <Button variant="outline" size="icon" onClick={() => router.push('/admin')}>
                    <ArrowLeft className="w-4 h-4" />
                </Button>
                <div>
                    <h1 className="text-3xl font-bold">Support Messages</h1>
                    <p className="text-muted-foreground">Respond to client inquiries</p>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 h-[calc(100vh-200px)]">
                {/* Conversations List */}
                <Card className="md:col-span-1 overflow-hidden flex flex-col">
                    <CardHeader>
                        <CardTitle className="text-lg">Conversations ({conversations.length})</CardTitle>
                    </CardHeader>
                    <CardContent className="flex-1 overflow-y-auto p-0">
                        {conversations.length === 0 ? (
                            <div className="p-6 text-center text-muted-foreground">
                                <MessageSquare className="w-12 h-12 mx-auto mb-2 opacity-50" />
                                <p>No conversations yet</p>
                            </div>
                        ) : (
                            conversations.map((conv) => (
                                <button
                                    key={conv.id}
                                    onClick={() => handleSelectConversation(conv)}
                                    className={cn(
                                        "w-full p-4 border-b text-left transition-colors hover:bg-secondary",
                                        selectedConversation?.id === conv.id && "bg-secondary"
                                    )}
                                >
                                    <div className="flex items-start justify-between mb-1">
                                        <div className="flex-1">
                                            <div className="font-medium text-sm">{conv.subject}</div>
                                            <div className="text-xs text-muted-foreground">{conv.userName}</div>
                                        </div>
                                        <div className="flex flex-col gap-1 items-end">
                                            {conv.unreadCount > 0 && (
                                                <Badge className="bg-primary text-xs">{conv.unreadCount}</Badge>
                                            )}
                                            <Badge variant={conv.status === 'OPEN' ? 'default' : 'secondary'} className="text-xs">
                                                {conv.status}
                                            </Badge>
                                        </div>
                                    </div>
                                    <div className="text-xs text-muted-foreground mt-1 truncate">
                                        {conv.lastMessage}
                                    </div>
                                    <div className="text-xs text-muted-foreground mt-1">
                                        {format(new Date(conv.lastMessageTime), "PPp")}
                                    </div>
                                </button>
                            ))
                        )}
                    </CardContent>
                </Card>

                {/* Chat Window */}
                <Card className="md:col-span-2 flex flex-col overflow-hidden">
                    {!selectedConversation ? (
                        <div className="flex-1 flex items-center justify-center text-muted-foreground">
                            <div className="text-center">
                                <MessageSquare className="w-16 h-16 mx-auto mb-4 opacity-50" />
                                <p>Select a conversation to start messaging</p>
                            </div>
                        </div>
                    ) : (
                        <>
                            <CardHeader className="border-b">
                                <div className="flex items-center justify-between">
                                    <div className="flex-1">
                                        <div className="flex items-center gap-2">
                                            <CardTitle className="text-lg">{selectedConversation.subject}</CardTitle>
                                            <Badge variant={selectedConversation.status === 'OPEN' ? 'default' : 'secondary'}>
                                                {selectedConversation.status}
                                            </Badge>
                                        </div>
                                        <div className="text-sm text-muted-foreground">
                                            {selectedConversation.userName} ({selectedConversation.userEmail})
                                        </div>
                                    </div>
                                    <div className="flex gap-2">
                                        {selectedConversation.status === 'OPEN' ? (
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                onClick={handleCloseConversation}
                                                className="gap-1"
                                            >
                                                <XCircle className="w-4 h-4" />
                                                Close
                                            </Button>
                                        ) : (
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                onClick={handleReopenConversation}
                                                className="gap-1"
                                            >
                                                <CheckCircle className="w-4 h-4" />
                                                Reopen
                                            </Button>
                                        )}
                                        <Button
                                            variant="destructive"
                                            size="sm"
                                            onClick={handleDeleteConversation}
                                            className="gap-1"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                            Delete
                                        </Button>
                                    </div>
                                </div>
                            </CardHeader>
                            <CardContent className="flex-1 overflow-y-auto p-4 space-y-4">
                                {messages.map((msg) => (
                                    <div
                                        key={msg.id}
                                        className={`flex ${msg.sender === 'ADMIN' ? 'justify-end' : 'justify-start'}`}
                                    >
                                        <div className={cn(
                                            "max-w-[80%] rounded-lg p-3",
                                            msg.sender === 'ADMIN'
                                                ? 'bg-primary text-primary-foreground'
                                                : 'bg-muted'
                                        )}>
                                            <p className="text-sm whitespace-pre-wrap">{msg.content}</p>
                                            <span className="text-[10px] opacity-70 block mt-1">
                                                {format(new Date(msg.createdAt), "p")}
                                            </span>
                                        </div>
                                    </div>
                                ))}
                            </CardContent>
                            <div className="p-4 border-t">
                                <form onSubmit={handleSendMessage} className="flex gap-2">
                                    <Input
                                        value={newMessage}
                                        onChange={(e) => setNewMessage(e.target.value)}
                                        placeholder="Type your response..."
                                        disabled={sending}
                                    />
                                    <Button type="submit" disabled={sending || !newMessage.trim()}>
                                        {sending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
                                    </Button>
                                </form>
                            </div>
                        </>
                    )}
                </Card>
            </div>
        </div>
    );
}

'use client'

import { useState, useEffect } from 'react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table'
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from '@/components/ui/select'
import { Input } from '@/components/ui/input'
import { Skeleton } from '@/components/ui/skeleton'
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from '@/components/ui/dialog'
import { Checkbox } from '@/components/ui/checkbox'
import { Search, Filter, CheckCircle, XCircle, Trash2, Star, Calendar, Eye, MessageSquare } from 'lucide-react'
import { toast } from 'sonner'
import Image from 'next/image'
import Link from 'next/link'

interface Review {
    id: string
    rating: number
    comment: string
    createdAt: string
    status: 'PENDING' | 'APPROVED' | 'HIDDEN'
    user: {
        name: string | null
        email: string
    }
    service: {
        id: string
        title: string
    }
    booking: {
        id: string
        date: string
    }
}

export default function AdminReviewsPage() {
    const [reviews, setReviews] = useState<Review[]>([])
    const [loading, setLoading] = useState(true)
    const [searchQuery, setSearchQuery] = useState('')
    const [statusFilter, setStatusFilter] = useState<'all' | 'PENDING' | 'APPROVED' | 'HIDDEN'>('all')
    const [selectedReviews, setSelectedReviews] = useState<string[]>([])
    const [bulkActionDialogOpen, setBulkActionDialogOpen] = useState(false)
    const [bulkAction, setBulkAction] = useState<'approve' | 'hide' | 'delete' | null>(null)
    const [processing, setProcessing] = useState(false)

    const fetchReviews = async () => {
        setLoading(true)
        try {
            const params = new URLSearchParams()
            if (searchQuery) params.set('search', searchQuery)
            if (statusFilter !== 'all') params.set('status', statusFilter)

            const res = await fetch(`/api/admin/reviews?${params.toString()}`)
            if (!res.ok) throw new Error('Failed to fetch reviews')
            const data = await res.json()
            setReviews(data.data || [])
        } catch (error) {
            console.error('Failed to fetch reviews', error)
        } finally {
            setLoading(false)
        }
    }

    useEffect(() => {
        fetchReviews()
    }, [searchQuery, statusFilter])

    const handleSelectAll = (checked: boolean) => {
        if (checked) {
            setSelectedReviews(reviews.map(r => r.id))
        } else {
            setSelectedReviews([])
        }
    }

    const handleSelectReview = (reviewId: string, checked: boolean) => {
        if (checked) {
            setSelectedReviews(prev => [...prev, reviewId])
        } else {
            setSelectedReviews(prev => prev.filter(id => id !== reviewId))
        }
    }

    const handleBulkAction = async () => {
        if (!bulkAction || selectedReviews.length === 0) return

        setProcessing(true)
        try {
            const res = await fetch('/api/admin/reviews', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    reviewIds: selectedReviews,
                    action: bulkAction
                })
            })

            if (!res.ok) throw new Error('Failed to perform action')
            const result = await res.json()

            toast.success(`${bulkAction === 'approve' ? 'Approved' : bulkAction === 'hide' ? 'Hidden' : 'Deleted'} ${result.updatedCount} reviews`)
            setSelectedReviews([])
            setBulkActionDialogOpen(false)
            setBulkAction(null)
            fetchReviews()
        } catch (error: any) {
            console.error('Bulk action failed', error)
            toast.error(error.message || 'Failed to perform action')
        } finally {
            setProcessing(false)
        }
    }

    const getStatusBadge = (status: string) => {
        switch (status) {
            case 'APPROVED':
                return <Badge className="bg-green-100 text-green-800">Approved</Badge>
            case 'HIDDEN':
                return <Badge variant="secondary">Hidden</Badge>
            case 'PENDING':
            default:
                return <Badge className="bg-yellow-100 text-yellow-800">Pending</Badge>
        }
    }

    const getStatusIcon = (status: string) => {
        switch (status) {
            case 'APPROVED':
                return <CheckCircle className="h-4 w-4 text-green-600" />
            case 'HIDDEN':
                return <XCircle className="h-4 w-4 text-gray-600" />
            case 'PENDING':
            default:
                return <MessageSquare className="h-4 w-4 text-yellow-600" />
        }
    }

    if (loading) {
        return (
            <div className="space-y-6">
                <div className="flex items-center justify-between">
                    <Skeleton className="h-8 w-48" />
                    <Skeleton className="h-10 w-32" />
                </div>
                <div className="flex gap-4">
                    <Skeleton className="h-10 flex-1" />
                    <Skeleton className="h-10 w-32" />
                </div>
                <div className="border rounded-lg">
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>Review</TableHead>
                                <TableHead>Service</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead>Date</TableHead>
                                <TableHead>Actions</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {[...Array(5)].map((_, i) => (
                                <TableRow key={i}>
                                    <TableCell><Skeleton className="h-12 w-48" /></TableCell>
                                    <TableCell><Skeleton className="h-4 w-24" /></TableCell>
                                    <TableCell><Skeleton className="h-4 w-20" /></TableCell>
                                    <TableCell><Skeleton className="h-4 w-24" /></TableCell>
                                    <TableCell><Skeleton className="h-8 w-24" /></TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                </div>
            </div>
        )
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-charcoal">Review Moderation</h1>
                    <p className="text-sm text-medium-gray">Manage and moderate customer reviews</p>
                </div>
                {selectedReviews.length > 0 && (
                    <div className="flex items-center gap-2">
                        <span className="text-sm text-medium-gray">
                            {selectedReviews.length} selected
                        </span>
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => {
                                setBulkAction('approve')
                                setBulkActionDialogOpen(true)
                            }}
                        >
                            <CheckCircle className="h-4 w-4 mr-2" />
                            Approve
                        </Button>
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => {
                                setBulkAction('hide')
                                setBulkActionDialogOpen(true)
                            }}
                        >
                            <XCircle className="h-4 w-4 mr-2" />
                            Hide
                        </Button>
                        <Button
                            variant="destructive"
                            size="sm"
                            onClick={() => {
                                setBulkAction('delete')
                                setBulkActionDialogOpen(true)
                            }}
                        >
                            <Trash2 className="h-4 w-4 mr-2" />
                            Delete
                        </Button>
                    </div>
                )}
            </div>

            {/* Filters */}
            <div className="flex flex-col sm:flex-row gap-4">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground h-4 w-4" />
                    <Input
                        placeholder="Search reviews..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="pl-10"
                    />
                </div>
                <Select value={statusFilter} onValueChange={(value: any) => setStatusFilter(value)}>
                    <SelectTrigger className="w-full sm:w-40">
                        <SelectValue placeholder="Status" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">All Status</SelectItem>
                        <SelectItem value="PENDING">Pending</SelectItem>
                        <SelectItem value="APPROVED">Approved</SelectItem>
                        <SelectItem value="HIDDEN">Hidden</SelectItem>
                    </SelectContent>
                </Select>
            </div>

            {/* Reviews Table */}
            <div className="border rounded-lg overflow-hidden">
                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead className="w-12">
                                <Checkbox
                                    checked={selectedReviews.length === reviews.length && reviews.length > 0}
                                    onCheckedChange={handleSelectAll}
                                />
                            </TableHead>
                            <TableHead>Review</TableHead>
                            <TableHead>Service</TableHead>
                            <TableHead>Status</TableHead>
                            <TableHead>Date</TableHead>
                            <TableHead className="text-right">Actions</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {reviews.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={6} className="text-center py-8 text-medium-gray">
                                    No reviews found
                                </TableCell>
                            </TableRow>
                        ) : (
                            reviews.map((review) => (
                                <TableRow key={review.id}>
                                    <TableCell>
                                        <Checkbox
                                            checked={selectedReviews.includes(review.id)}
                                            onCheckedChange={(checked) => handleSelectReview(review.id, checked as boolean)}
                                        />
                                    </TableCell>
                                    <TableCell>
                                        <div className="space-y-2">
                                            <div className="flex items-center gap-2">
                                                <div className="flex items-center">
                                                    {[...Array(5)].map((_, i) => (
                                                        <Star
                                                            key={i}
                                                            className={`h-4 w-4 ${
                                                                i < review.rating
                                                                    ? 'text-yellow-500 fill-current'
                                                                    : 'text-gray-300'
                                                            }`}
                                                        />
                                                    ))}
                                                </div>
                                                {getStatusIcon(review.status)}
                                            </div>
                                            <div className="flex items-center gap-2 text-sm">
                                                <span className="font-medium text-charcoal">
                                                    {review.user.name || 'Anonymous'}
                                                </span>
                                                <span className="text-medium-gray">ΓÇó</span>
                                                <span className="text-medium-gray">{review.user.email}</span>
                                            </div>
                                            <p className="text-sm text-medium-gray line-clamp-2">
                                                {review.comment}
                                            </p>
                                        </div>
                                    </TableCell>
                                    <TableCell>
                                        <Link
                                            href={`/services/${review.service.id}`}
                                            className="text-sm font-medium text-primary hover:underline"
                                        >
                                            {review.service.title}
                                        </Link>
                                    </TableCell>
                                    <TableCell>
                                        {getStatusBadge(review.status)}
                                    </TableCell>
                                    <TableCell>
                                        <div className="flex items-center gap-1 text-sm text-medium-gray">
                                            <Calendar className="h-3 w-3" />
                                            {new Date(review.createdAt).toLocaleDateString()}
                                        </div>
                                    </TableCell>
                                    <TableCell className="text-right">
                                        <div className="flex items-center justify-end gap-1">
                                            <Link href={`/services/${review.service.id}#reviews`} target="_blank">
                                                <Button variant="ghost" size="sm">
                                                    <Eye className="h-4 w-4" />
                                                </Button>
                                            </Link>
                                        </div>
                                    </TableCell>
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </div>

            {/* Bulk Action Confirmation Dialog */}
            <Dialog open={bulkActionDialogOpen} onOpenChange={setBulkActionDialogOpen}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>
                            {bulkAction === 'approve' && 'Approve Reviews'}
                            {bulkAction === 'hide' && 'Hide Reviews'}
                            {bulkAction === 'delete' && 'Delete Reviews'}
                        </DialogTitle>
                        <DialogDescription>
                            Are you sure you want to {bulkAction} {selectedReviews.length} review(s)?
                            {bulkAction === 'delete' && ' This action cannot be undone.'}
                            {bulkAction === 'approve' && ' Approved reviews will be visible to customers and affect service ratings.'}
                            {bulkAction === 'hide' && ' Hidden reviews will not be visible to customers and will not affect service ratings.'}
                        </DialogDescription>
                    </DialogHeader>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setBulkActionDialogOpen(false)}>
                            Cancel
                        </Button>
                        <Button
                            variant={bulkAction === 'delete' ? 'destructive' : 'default'}
                            onClick={handleBulkAction}
                            disabled={processing}
                        >
                            {processing ? 'Processing...' : `${bulkAction === 'approve' ? 'Approve' : bulkAction === 'hide' ? 'Hide' : 'Delete'} ${selectedReviews.length} Review(s)`}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    )
}

import {
