                                        }>
                                            {req.status}
                                        </Badge>
                                    </TableCell>
                                    <TableCell className="whitespace-nowrap text-muted-foreground">
                                        {format(new Date(req.createdAt), "MMM d, HH:mm")}
                                    </TableCell>
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { signIn } from 'next-auth/react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Compass, Loader2, Lock } from 'lucide-react';
import { toast } from 'sonner';

export default function AdminLoginPage() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const [loading, setLoading] = useState(false);
    const [formData, setFormData] = useState({
        email: '',
        password: ''
    });

    const callbackUrl = searchParams.get('callbackUrl') || '/admin';

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);

        try {
            const result = await signIn('credentials', {
                email: formData.email,
                password: formData.password,
                redirect: false,
            });

            if (result?.error) {
                toast.error('Invalid credentials. Please try again.');
            } else {
                // Wait a moment for session to update
                await new Promise(resolve => setTimeout(resolve, 100));
                router.refresh();

                // Verify admin role before redirecting
                const sessionRes = await fetch('/api/auth/me');
                const sessionData = await sessionRes.json();

                if (sessionData?.user?.role === 'ADMIN') {
                    toast.success('Welcome back, Admin!');
                    router.push(callbackUrl.startsWith('/admin') ? callbackUrl : '/admin/dashboard');
                } else {
                    toast.error('Access denied. Admin privileges required.');
                }
            }
        } catch (error) {
            toast.error('An unexpected error occurred.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex min-h-screen items-center justify-center bg-white relative overflow-hidden">
            {/* Background Decor */}
            <div className="absolute inset-0 z-0">
                <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-orange-100/50 rounded-full blur-3xl -mr-32 -mt-32" />
                <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-orange-50/50 rounded-full blur-3xl -ml-32 -mb-32" />
            </div>

            <Card className="w-full max-w-md relative z-10 border-none shadow-2xl bg-white">
                <CardHeader className="text-center pb-8 pt-10">
                    <div className="flex justify-center mb-6">
                        <div className="w-16 h-16 bg-gradient-to-br from-[#FF5F00] to-[#E55500] rounded-2xl flex items-center justify-center shadow-lg shadow-orange-500/20 transform rotate-3">
                            <Compass className="w-8 h-8 text-white" />
                        </div>
                    </div>
                    <CardTitle className="text-2xl font-bold tracking-tight text-gray-900">
                        Admin Portal
                    </CardTitle>
                    <CardDescription className="text-gray-500 font-medium">
                        Explore Marrakesh Management
                    </CardDescription>
                </CardHeader>
                <CardContent className="px-8 pb-10">
                    <form onSubmit={handleSubmit} className="space-y-6">
                        <div className="space-y-2">
                            <Label htmlFor="email">Email Address</Label>
                            <Input
                                id="email"
                                type="email"
                                placeholder="admin@exploremarrakesh.com"
                                className="h-11 bg-white/50 focus:bg-white transition-all"
                                value={formData.email}
                                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                                required
                            />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="password">Password</Label>
                            <Input
                                id="password"
                                type="password"
                                placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                                className="h-11 bg-white/50 focus:bg-white transition-all"
                                value={formData.password}
                                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                                required
                            />
                        </div>

                        <Button
                            type="submit"
                            className="w-full h-11 bg-[#FF5F00] hover:bg-[#E55500] text-white font-bold shadow-lg shadow-orange-500/20 transition-all hover:-translate-y-0.5"
                            disabled={loading}
                        >
                            {loading ? (
                                <>
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                    Authenticating...
                                </>
                            ) : (
                                <>
                                    <Lock className="mr-2 h-4 w-4" />
                                    Secure Login
                                </>
                            )}
                        </Button>
                    </form>
                </CardContent>
            </Card>

            <div className="absolute bottom-6 text-center text-xs text-gray-400 font-medium">
                &copy; 2024 Explore Marrakesh. Secure Admin Access.
            </div>
        </div>
    );
}

import { NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/authorization';
import { errorResponse, successResponse } from '@/lib/api-response';
import prisma from '@/lib/prisma';
import { subDays, startOfDay, endOfDay } from 'date-fns';
import { decimalToNumber } from '@/lib/decimal';

export async function GET(request: Request) {
    try {
        await requireAdmin();

        const { searchParams } = new URL(request.url);
        const range = searchParams.get('range') || '30d';

        const days = range === '7d' ? 7 : range === '90d' ? 90 : 30;
        const startDate = startOfDay(subDays(new Date(), days));
        const previousStartDate = startOfDay(subDays(startDate, days));
        const previousEndDate = endOfDay(subDays(startDate, 1));

        // Revenue calculations
        const revenueThisPeriod = await prisma.booking.aggregate({
            where: {
                date: { gte: startDate },
                status: { not: 'CANCELLED' }
            },
            _sum: { totalPrice: true }
        });

        const revenuePreviousPeriod = await prisma.booking.aggregate({
            where: {
                date: { gte: previousStartDate, lte: previousEndDate },
                status: { not: 'CANCELLED' }
            },
            _sum: { totalPrice: true }
        });

        const revenueToday = await prisma.booking.aggregate({
            where: {
                date: { gte: startOfDay(new Date()), lte: endOfDay(new Date()) },
                status: { not: 'CANCELLED' }
            },
            _sum: { totalPrice: true }
        });

        const revenueWeek = await prisma.booking.aggregate({
            where: {
                date: { gte: startOfDay(subDays(new Date(), 7)) },
                status: { not: 'CANCELLED' }
            },
            _sum: { totalPrice: true }
        });

        const revenueMonth = await prisma.booking.aggregate({
            where: {
                date: { gte: startOfDay(subDays(new Date(), 30)) },
                status: { not: 'CANCELLED' }
            },
            _sum: { totalPrice: true }
        });

        const totalRevenue = await prisma.booking.aggregate({
            where: {
                status: { not: 'CANCELLED' }
            },
            _sum: { totalPrice: true }
        });

        // Bookings calculations
        const bookingsThisPeriod = await prisma.booking.count({
            where: {
                date: { gte: startDate },
                status: { not: 'CANCELLED' }
            }
        });

        const bookingsPreviousPeriod = await prisma.booking.count({
            where: {
                date: { gte: previousStartDate, lte: previousEndDate },
                status: { not: 'CANCELLED' }
            }
        });

        const bookingsToday = await prisma.booking.count({
            where: {
                date: { gte: startOfDay(new Date()), lte: endOfDay(new Date()) },
                status: { not: 'CANCELLED' }
            }
        });

        const bookingsWeek = await prisma.booking.count({
            where: {
                date: { gte: startOfDay(subDays(new Date(), 7)) },
                status: { not: 'CANCELLED' }
            }
        });

        const bookingsMonth = await prisma.booking.count({
            where: {
                date: { gte: startOfDay(subDays(new Date(), 30)) },
                status: { not: 'CANCELLED' }
            }
        });

        const totalBookings = await prisma.booking.count({
            where: {
                status: { not: 'CANCELLED' }
            }
        });

        // Users
        const totalUsers = await prisma.user.count();
        const newUsersThisWeek = await prisma.user.count({
            where: {
                createdAt: { gte: startOfDay(subDays(new Date(), 7)) }
            }
        });

        // Top services
        const topServicesData = await prisma.booking.groupBy({
            by: ['activityId', 'activityTitle'],
            where: {
                date: { gte: startDate },
                status: { not: 'CANCELLED' }
            },
            _count: { id: true },
            _sum: { totalPrice: true },
            orderBy: { _sum: { totalPrice: 'desc' } },
            take: 5
        });

        const topServices = await Promise.all(
            topServicesData
                .filter(item => item.activityId) // Filter out null activityIds
                .map(async (item) => {
                    let serviceTitle = item.activityTitle;
                    if (item.activityId) {
                        try {
                            const service = await prisma.service.findUnique({
                                where: { id: item.activityId },
                                select: { title: true }
                            });
                            if (service?.title) {
                                serviceTitle = service.title;
                            }
                        } catch (error) {
                            // If service not found, use activityTitle from booking
                            console.warn(`Service ${item.activityId} not found, using activityTitle`);
                        }
                    }
                    return {
                        id: item.activityId || 'unknown',
                        title: serviceTitle || 'Unknown Service',
                        bookings: item._count.id,
                        revenue: item._sum.totalPrice || 0
                    };
                })
        );

        // Calculate percentage changes
        const revenueThis = decimalToNumber(revenueThisPeriod._sum.totalPrice);
        const revenuePrev = decimalToNumber(revenuePreviousPeriod._sum.totalPrice);
        const revenueTodayValue = decimalToNumber(revenueToday._sum.totalPrice);
        const revenueWeekValue = decimalToNumber(revenueWeek._sum.totalPrice);
        const revenueMonthValue = decimalToNumber(revenueMonth._sum.totalPrice);
        const revenueTotalValue = decimalToNumber(totalRevenue._sum.totalPrice);

        const revenueChange = revenuePrev
            ? ((revenueThis - revenuePrev) / (revenuePrev || 1)) * 100
            : 0;

        const bookingsChange = bookingsPreviousPeriod
            ? ((bookingsThisPeriod - bookingsPreviousPeriod) / bookingsPreviousPeriod) * 100
            : 0;

        const analytics = {
            revenue: {
                today: revenueTodayValue,
                week: revenueWeekValue,
                month: revenueMonthValue,
                total: revenueTotalValue,
                change: revenueChange
            },
            bookings: {
                today: bookingsToday,
                week: bookingsWeek,
                month: bookingsMonth,
                total: totalBookings,
                change: bookingsChange
            },
            users: {
                total: totalUsers,
                newThisWeek: newUsersThisWeek,
                change: 0 // Can be calculated if needed
            },
            topServices,
            recentTrends: [] // Can be enhanced with daily breakdown
        };

        return successResponse(analytics);
    } catch (error) {
        return errorResponse(error);
    }
}

