"use client";

import { usePathname } from "next/navigation";
import Link from "next/link";
import { useSession, signOut } from "next-auth/react";
import {
    LayoutDashboard,
    Calendar,
    MessageSquare,
    User,
    CreditCard,
    LogOut,
    Menu,
    X,
    ChevronLeft,
    ChevronRight
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { useState, useEffect } from "react";

const navigation = [
    { name: "Dashboard", href: "/client", icon: LayoutDashboard },
    { name: "My Bookings", href: "/client/bookings", icon: Calendar },
    { name: "Messages", href: "/client/messages", icon: MessageSquare },
    { name: "Profile", href: "/client/profile", icon: User },
    { name: "Payments", href: "/client/payments", icon: CreditCard },
];

export default function ClientLayout({
    children,
}: {
    children: React.ReactNode;
}) {
    const pathname = usePathname();
    const { data: session } = useSession();
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

    // Load sidebar state from localStorage
    useEffect(() => {
        const saved = localStorage.getItem('sidebarCollapsed');
        if (saved !== null) {
            setSidebarCollapsed(JSON.parse(saved));
        }
    }, []);

    // Save sidebar state to localStorage
    useEffect(() => {
        localStorage.setItem('sidebarCollapsed', JSON.stringify(sidebarCollapsed));
    }, [sidebarCollapsed]);

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Mobile sidebar backdrop */}
            {sidebarOpen && (
                <div
                    className="fixed inset-0 bg-gray-100 z-40 lg:hidden"
                    onClick={() => setSidebarOpen(false)}
                />
            )}

            {/* Sidebar */}
            <aside
                className={`fixed top-0 left-0 z-50 h-full bg-white border-r border-gray-200 transform transition-all duration-300 ease-in-out lg:translate-x-0 ${
                    sidebarOpen ? "translate-x-0" : "-translate-x-full"
                } ${
                    sidebarCollapsed ? "w-20" : "w-64"
                }`}
            >
                <div className="flex flex-col h-full">
                    {/* Logo & Toggle */}
                    <div className="flex items-center justify-between h-16 px-4 border-b border-gray-200">
                        {!sidebarCollapsed && (
                            <Link href="/" className="flex items-center gap-2 flex-1">
                                <span className="text-xl font-bold text-[#FF5F00] whitespace-nowrap">
                                    Explore Marrakesh
                                </span>
                            </Link>
                        )}
                        {sidebarCollapsed && (
                            <Link href="/" className="flex items-center justify-center w-full">
                                <span className="text-2xl font-bold text-[#FF5F00]">E</span>
                            </Link>
                        )}
                        <div className="flex items-center gap-2">
                            <button
                                onClick={() => setSidebarCollapsed(!sidebarCollapsed)}
                                className="hidden lg:flex items-center justify-center w-8 h-8 rounded-md text-gray-500 hover:text-gray-700 hover:bg-gray-100 transition-colors"
                                title={sidebarCollapsed ? "Expand sidebar" : "Collapse sidebar"}
                            >
                                {sidebarCollapsed ? (
                                    <ChevronRight className="w-4 h-4" />
                                ) : (
                                    <ChevronLeft className="w-4 h-4" />
                                )}
                            </button>
                            <button
                                onClick={() => setSidebarOpen(false)}
                                className="lg:hidden text-gray-500 hover:text-gray-700"
                            >
                                <X className="w-6 h-6" />
                            </button>
                        </div>
                    </div>

                    {/* User info */}
                    <div className={`px-4 py-4 border-b border-gray-200 ${sidebarCollapsed ? "px-2" : ""}`}>
                        <div className={`flex items-center gap-3 ${sidebarCollapsed ? "justify-center" : ""}`}>
                            <div className="w-10 h-10 rounded-full bg-[#FF5F00] flex items-center justify-center text-white font-semibold flex-shrink-0">
                                {session?.user?.name?.[0]?.toUpperCase() || "U"}
                            </div>
                            {!sidebarCollapsed && (
                                <div className="flex-1 min-w-0">
                                    <p className="text-sm font-medium text-gray-900 truncate">
                                        {session?.user?.name || "User"}
                                    </p>
                                    <p className="text-xs text-gray-500 truncate">
                                        {session?.user?.email}
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Navigation */}
                    <nav className="flex-1 px-2 py-4 space-y-1 overflow-y-auto">
                        {navigation.map((item) => {
                            const isActive = pathname === item.href;
                            return (
                                <Link
                                    key={item.name}
                                    href={item.href}
                                    onClick={() => setSidebarOpen(false)}
                                    className={`flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all group ${
                                        sidebarCollapsed ? "justify-center px-2" : ""
                                    } ${
                                        isActive
                                            ? "bg-orange-50 text-[#FF5F00]"
                                            : "text-gray-700 hover:bg-gray-100"
                                    }`}
                                    title={sidebarCollapsed ? item.name : undefined}
                                >
                                    <item.icon className={`w-5 h-5 flex-shrink-0 ${isActive ? "text-[#FF5F00]" : ""}`} />
                                    {!sidebarCollapsed && (
                                        <span className="whitespace-nowrap">{item.name}</span>
                                    )}
                                </Link>
                            );
                        })}
                    </nav>

                    {/* Logout */}
                    <div className={`p-4 border-t border-gray-200 ${sidebarCollapsed ? "px-2" : ""}`}>
                        <Button
                            variant="ghost"
                            className={`w-full text-gray-700 hover:text-red-600 hover:bg-red-50 ${
                                sidebarCollapsed ? "justify-center px-2" : "justify-start"
                            }`}
                            onClick={() => signOut({ callbackUrl: "/" })}
                            title={sidebarCollapsed ? "Sign Out" : undefined}
                        >
                            <LogOut className="w-5 h-5 flex-shrink-0" />
                            {!sidebarCollapsed && <span className="ml-3">Sign Out</span>}
                        </Button>
                    </div>
                </div>
            </aside>

            {/* Main content */}
            <div className={`transition-all duration-300 ${sidebarCollapsed ? "lg:pl-20" : "lg:pl-64"}`}>
                {/* Mobile header */}
                <header className="sticky top-0 z-30 flex items-center h-16 px-4 bg-white border-b border-gray-200 lg:hidden">
                    <button
                        onClick={() => setSidebarOpen(true)}
                        className="text-gray-500 hover:text-gray-700"
                    >
                        <Menu className="w-6 h-6" />
                    </button>
                    <span className="ml-4 text-lg font-semibold text-gray-900">
                        Client Dashboard
                    </span>
                </header>

                {/* Page content */}
                <main className="p-6 lg:p-8">
                    <div className="max-w-7xl mx-auto">{children}</div>
                </main>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { MessageSquare, Send, Plus, AlertCircle } from "lucide-react";
import { toast } from "sonner";

interface Message {
    id: string;
    content: string;
    sender: string;
    createdAt: string;
    read: boolean;
}

interface Conversation {
    id: string;
    subject: string;
    status: string;
    createdAt: string;
    updatedAt: string;
    messages: Message[];
}

export default function MessagesPage() {
    const [conversations, setConversations] = useState<Conversation[]>([]);
    const [activeConversation, setActiveConversation] =
        useState<Conversation | null>(null);
    const [loading, setLoading] = useState(true);
    const [sending, setSending] = useState(false);
    const [newMessage, setNewMessage] = useState("");
    const [dialogOpen, setDialogOpen] = useState(false);
    const [newSubject, setNewSubject] = useState("");
    const [newContent, setNewContent] = useState("");
    const messagesEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        fetchConversations();
    }, []);

    useEffect(() => {
        if (activeConversation) {
            fetchConversationMessages(activeConversation.id);
        }
    }, [activeConversation?.id]);

    useEffect(() => {
        scrollToBottom();
    }, [activeConversation?.messages]);

    const fetchConversationMessages = async (conversationId: string) => {
        try {
            const res = await fetch(`/api/conversations/${conversationId}/messages`);
            if (!res.ok) throw new Error("Failed to fetch messages");
            const data = await res.json();
            const messages = data.data || data;
            setActiveConversation(prev => prev ? { ...prev, messages } : null);
        } catch (error) {
            console.error("Error fetching messages:", error);
            toast.error("Failed to load messages");
        }
    };

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    const fetchConversations = async () => {
        try {
            const res = await fetch("/api/conversations");
            if (!res.ok) throw new Error("Failed to fetch conversations");
            const data = await res.json();
            // Handle wrapped response
            const conversationsData = data.data || data;
            setConversations(conversationsData);
            if (conversationsData.length > 0 && !activeConversation) {
                setActiveConversation(conversationsData[0]);
            }
        } catch (error) {
            console.error("Error fetching conversations:", error);
            toast.error("Failed to load messages");
        } finally {
            setLoading(false);
        }
    };

    const handleSendMessage = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newMessage.trim() || !activeConversation) return;

        setSending(true);
        try {
            const res = await fetch(
                `/api/conversations/${activeConversation.id}/messages`,
                {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ content: newMessage }),
                }
            );

            if (!res.ok) throw new Error("Failed to send message");

            setNewMessage("");
            // Refresh messages for the active conversation
            await fetchConversationMessages(activeConversation.id);
            // Refresh conversations list
            await fetchConversations();
        } catch (error) {
            console.error("Error sending message:", error);
            toast.error("Failed to send message");
        } finally {
            setSending(false);
        }
    };

    const handleCreateConversation = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newSubject.trim() || !newContent.trim()) return;

        try {
            const res = await fetch("/api/conversations", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ subject: newSubject, content: newContent }),
            });

            if (!res.ok) throw new Error("Failed to create conversation");

            toast.success("Conversation created successfully");
            setNewSubject("");
            setNewContent("");
            setDialogOpen(false);
            await fetchConversations();
        } catch (error) {
            console.error("Error creating conversation:", error);
            toast.error("Failed to create conversation");
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <div className="text-center">
                    <div className="w-16 h-16 border-4 border-[#FF5F00] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                    <p className="text-gray-600">Loading messages...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900">Messages</h1>
                    <p className="text-gray-600 mt-1">
                        Chat with our support team
                    </p>
                </div>
                <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
                    <DialogTrigger asChild>
                        <Button>
                            <Plus className="w-4 h-4 mr-2" />
                            New Conversation
                        </Button>
                    </DialogTrigger>
                    <DialogContent>
                        <DialogHeader>
                            <DialogTitle>Start New Conversation</DialogTitle>
                            <DialogDescription>
                                Create a new support ticket to get help
                            </DialogDescription>
                        </DialogHeader>
                        <form onSubmit={handleCreateConversation} className="space-y-4">
                            <div>
                                <Label htmlFor="subject">Subject</Label>
                                <Input
                                    id="subject"
                                    value={newSubject}
                                    onChange={(e) => setNewSubject(e.target.value)}
                                    placeholder="What do you need help with?"
                                    required
                                />
                            </div>
                            <div>
                                <Label htmlFor="message">Message</Label>
                                <Textarea
                                    id="message"
                                    value={newContent}
                                    onChange={(e) => setNewContent(e.target.value)}
                                    placeholder="Describe your issue..."
                                    rows={4}
                                    required
                                />
                            </div>
                            <Button type="submit" className="w-full">
                                Create Conversation
                            </Button>
                        </form>
                    </DialogContent>
                </Dialog>
            </div>

            {conversations.length === 0 ? (
                <Card>
                    <CardContent className="py-12 text-center">
                        <MessageSquare className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                        <h3 className="text-lg font-semibold text-gray-900 mb-2">
                            No conversations yet
                        </h3>
                        <p className="text-gray-600 mb-4">
                            Start a conversation to get help from our support team
                        </p>
                        <Button onClick={() => setDialogOpen(true)}>
                            <Plus className="w-4 h-4 mr-2" />
                            Start Conversation
                        </Button>
                    </CardContent>
                </Card>
            ) : (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Conversations List */}
                    <Card className="lg:col-span-1">
                        <CardHeader>
                            <CardTitle>Conversations</CardTitle>
                        </CardHeader>
                        <CardContent className="p-0">
                            <div className="divide-y">
                                {conversations.map((conv) => (
                                    <button
                                        key={conv.id}
                                        onClick={() => setActiveConversation(conv)}
                                        className={`w-full text-left p-4 hover:bg-gray-50 transition-colors ${activeConversation?.id === conv.id ? "bg-orange-50" : ""
                                            }`}
                                    >
                                        <div className="flex items-start justify-between mb-1">
                                            <h4 className="font-medium text-gray-900 text-sm">
                                                {conv.subject}
                                            </h4>
                                            <span
                                                className={`text-xs px-2 py-0.5 rounded ${conv.status === "OPEN"
                                                        ? "bg-green-100 text-green-800"
                                                        : "bg-gray-100 text-gray-800"
                                                    }`}
                                            >
                                                {conv.status}
                                            </span>
                                        </div>
                                        <p className="text-xs text-gray-500">
                                            {new Date(conv.updatedAt).toLocaleDateString()}
                                        </p>
                                    </button>
                                ))}
                            </div>
                        </CardContent>
                    </Card>

                    {/* Active Conversation */}
                    <Card className="lg:col-span-2">
                        {activeConversation ? (
                            <>
                                <CardHeader className="border-b">
                                    <CardTitle>{activeConversation.subject}</CardTitle>
                                </CardHeader>
                                <CardContent className="p-0">
                                    <div className="h-[400px] overflow-y-auto p-4 space-y-4">
                                        {activeConversation.messages.map((message) => (
                                            <div
                                                key={message.id}
                                                className={`flex ${message.sender === "USER"
                                                        ? "justify-end"
                                                        : "justify-start"
                                                    }`}
                                            >
                                                <div
                                                    className={`max-w-[70%] rounded-lg p-3 ${message.sender === "USER"
                                                            ? "bg-[#FF5F00] text-white"
                                                            : "bg-gray-100 text-gray-900"
                                                        }`}
                                                >
                                                    <p className="text-sm">{message.content}</p>
                                                    <p
                                                        className={`text-xs mt-1 ${message.sender === "USER"
                                                                ? "text-orange-100"
                                                                : "text-gray-500"
                                                            }`}
                                                    >
                                                        {new Date(message.createdAt).toLocaleTimeString(
                                                            "en-US",
                                                            {
                                                                hour: "2-digit",
                                                                minute: "2-digit",
                                                            }
                                                        )}
                                                    </p>
                                                </div>
                                            </div>
                                        ))}
                                        <div ref={messagesEndRef} />
                                    </div>
                                    <div className="border-t p-4">
                                        <form onSubmit={handleSendMessage} className="flex gap-2">
                                            <Input
                                                value={newMessage}
                                                onChange={(e) => setNewMessage(e.target.value)}
                                                placeholder="Type your message..."
                                                disabled={sending}
                                            />
                                            <Button type="submit" disabled={sending}>
                                                <Send className="w-4 h-4" />
                                            </Button>
                                        </form>
                                    </div>
                                </CardContent>
                            </>
                        ) : (
                            <CardContent className="py-12 text-center">
                                <MessageSquare className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                                <p className="text-gray-600">Select a conversation to view</p>
                            </CardContent>
                        )}
                    </Card>
                </div>
            )}
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Bell, Check, AlertCircle } from "lucide-react";
import { toast } from "sonner";

interface Notification {
    id: string;
    type: string;
    title: string;
    message: string;
    read: boolean;
    createdAt: string;
}

export default function NotificationsPage() {
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState("all");

    useEffect(() => {
        fetchNotifications();
    }, []);

    const fetchNotifications = async () => {
        try {
            const res = await fetch("/api/notifications");
            if (!res.ok) throw new Error("Failed to fetch notifications");
            const data = await res.json();
            // Handle wrapped response
            const notificationsData = data.data || data;
            setNotifications(notificationsData);
        } catch (error) {
            console.error("Error fetching notifications:", error);
            toast.error("Failed to load notifications");
        } finally {
            setLoading(false);
        }
    };

    const markAsRead = async (id: string) => {
        try {
            const res = await fetch(`/api/notifications/${id}/read`, {
                method: "PATCH",
            });
            
            const data = await res.json();
            
            if (!res.ok) {
                // Handle error response
                const errorMessage = data.error?.message || data.error || `Failed to mark as read (${res.status})`;
                throw new Error(errorMessage);
            }
            
            // Handle success response (may be wrapped in data field)
            const notification = data.data || data;
            
            // Optimistically update the notification in the list
            setNotifications((prev) =>
                prev.map((n) => (n.id === id ? { ...n, read: true } : n))
            );
            
            toast.success("Notification marked as read");
        } catch (error: any) {
            console.error("Error marking notification as read:", error);
            toast.error(error.message || "Failed to update notification");
        }
    };

    const filterNotifications = (filter: string) => {
        switch (filter) {
            case "unread":
                return notifications.filter((n) => !n.read);
            case "read":
                return notifications.filter((n) => n.read);
            default:
                return notifications;
        }
    };

    const getNotificationIcon = (type: string) => {
        switch (type) {
            case "BOOKING_CONFIRMED":
            case "BOOKING_COMPLETED":
                return "bg-green-100 text-green-600";
            case 'BOOKING':
                return "bg-blue-100 text-blue-600";
            case "BOOKING_CANCELLED":
            case "BOOKING_REJECTED":
                return "bg-red-100 text-red-600";
            default:
                return "bg-blue-100 text-blue-600";
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <div className="text-center">
                    <div className="w-16 h-16 border-4 border-[#FF5F00] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                    <p className="text-gray-600">Loading notifications...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-3xl font-bold text-gray-900">Notifications</h1>
                <p className="text-gray-600 mt-1">
                    Stay updated with your booking activities
                </p>
            </div>

            <Tabs value={activeTab} onValueChange={setActiveTab}>
                <TabsList>
                    <TabsTrigger value="all">
                        All ({notifications.length})
                    </TabsTrigger>
                    <TabsTrigger value="unread">
                        Unread ({notifications.filter((n) => !n.read).length})
                    </TabsTrigger>
                    <TabsTrigger value="read">
                        Read ({notifications.filter((n) => n.read).length})
                    </TabsTrigger>
                </TabsList>

                <TabsContent value={activeTab} className="mt-6">
                    {filterNotifications(activeTab).length > 0 ? (
                        <div className="space-y-3">
                            {filterNotifications(activeTab).map((notification) => (
                                <Card
                                    key={notification.id}
                                    className={`${!notification.read ? "border-l-4 border-l-[#FF5F00]" : ""
                                        }`}
                                >
                                    <CardContent className="p-4">
                                        <div className="flex items-start gap-4">
                                            <div
                                                className={`w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 ${getNotificationIcon(
                                                    notification.type
                                                )}`}
                                            >
                                                <Bell className="w-5 h-5" />
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-start justify-between gap-4">
                                                    <div>
                                                        <h3
                                                            className={`font-semibold ${!notification.read
                                                                ? "text-gray-900"
                                                                : "text-gray-600"
                                                                }`}
                                                        >
                                                            {notification.title}
                                                        </h3>
                                                        <p className="text-sm text-gray-600 mt-1">
                                                            {notification.message}
                                                        </p>
                                                        <p className="text-xs text-gray-500 mt-2">
                                                            {new Date(
                                                                notification.createdAt
                                                            ).toLocaleDateString("en-US", {
                                                                year: "numeric",
                                                                month: "long",
                                                                day: "numeric",
                                                                hour: "2-digit",
                                                                minute: "2-digit",
                                                            })}
                                                        </p>
                                                    </div>
                                                    {!notification.read && (
                                                        <Button
                                                            variant="ghost"
                                                            size="sm"
                                                            onClick={() => markAsRead(notification.id)}
                                                        >
                                                            <Check className="w-4 h-4 mr-2" />
                                                            Mark as read
                                                        </Button>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    </CardContent>
                                </Card>
                            ))}
                        </div>
                    ) : (
                        <Card>
                            <CardContent className="py-12 text-center">
                                <AlertCircle className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                                <h3 className="text-lg font-semibold text-gray-900 mb-2">
                                    No {activeTab} notifications
                                </h3>
                                <p className="text-gray-600">
                                    {activeTab === "unread"
                                        ? "You're all caught up!"
                                        : "No notifications to show"}
                                </p>
                            </CardContent>
                        </Card>
                    )}
                </TabsContent>
            </Tabs>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { useSession } from "next-auth/react";
import Link from "next/link";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { SkeletonStatsCard, SkeletonBookingCard } from "@/components/ui/skeleton";
import {
    Calendar,
    MessageSquare,
    Bell,
    ArrowRight,
    Clock,
    CheckCircle,
    Compass,
    Sparkles,
    MapPin
} from "lucide-react";
import { toast } from "sonner";

interface DashboardStats {
    bookings: {
        total: number;
        upcoming: number;
        completed: number;
        cancelled: number;
    };
    notifications: {
        unread: number;
    };
    nextBooking: {
        id: string;
        activityTitle: string;
        date: string;
        status: string;
    } | null;
}

export default function ClientDashboard() {
    const { data: session } = useSession();
    const [stats, setStats] = useState<DashboardStats | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchDashboardStats();
    }, []);

    const fetchDashboardStats = async () => {
        try {
            const [bookingsRes, notificationsRes] = await Promise.all([
                fetch("/api/bookings"),
                fetch("/api/notifications"),
            ]);

            if (!bookingsRes.ok || !notificationsRes.ok) {
                throw new Error("Failed to fetch dashboard data");
            }

            const bookingsData = await bookingsRes.json();
            const notificationsData = await notificationsRes.json();
            
            // Handle wrapped responses
            const bookings = bookingsData.data || bookingsData;
            const notifications = notificationsData.data || notificationsData;

            const now = new Date();
            const upcoming = bookings.filter(
                (b: any) =>
                    (b.status === "PENDING" || b.status === "CONFIRMED") &&
                    new Date(b.date) > now
            );
            const completed = bookings.filter((b: any) => b.status === "COMPLETED");
            const cancelled = bookings.filter(
                (b: any) => b.status === "CANCELLED" || b.status === "REJECTED"
            );

            const nextBooking = upcoming.length > 0 ? upcoming[0] : null;

            setStats({
                bookings: {
                    total: bookings.length,
                    upcoming: upcoming.length,
                    completed: completed.length,
                    cancelled: cancelled.length,
                },
                notifications: {
                    unread: notifications.filter((n: any) => !n.read).length,
                },
                nextBooking,
            });
        } catch (error) {
            console.error("Error fetching dashboard stats:", error);
            toast.error("Failed to load dashboard data");
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="space-y-6">
                <div>
                    <div className="h-8 w-64 bg-muted/60 rounded-lg animate-pulse mb-2" />
                    <div className="h-5 w-48 bg-muted/40 rounded-lg animate-pulse" />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    {[...Array(4)].map((_, i) => (
                        <SkeletonStatsCard key={i} />
                    ))}
                </div>
                <SkeletonBookingCard />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {/* Welcome Section */}
            <div className="bg-gradient-to-r from-primary/10 via-primary/5 to-transparent rounded-2xl p-6 border border-primary/10">
                <div className="flex items-start justify-between">
                    <div>
                        <h1 className="text-2xl sm:text-3xl font-bold text-charcoal">
                            Welcome back, {session?.user?.name?.split(" ")[0] || "there"}! ≡ƒæï
                        </h1>
                        <p className="text-medium-gray mt-1">
                            Here's what's happening with your Marrakech adventures
                        </p>
                    </div>
                    <Link href="/services" className="hidden sm:block">
                        <Button className="rounded-full shadow-md shadow-primary/20">
                            <Compass className="w-4 h-4 mr-2" />
                            Explore
                        </Button>
                    </Link>
                </div>
            </div>

            {/* Stats Grid */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <Card className="border-0 shadow-sm hover:shadow-md transition-shadow">
                    <CardContent className="pt-5 pb-5">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs font-medium text-medium-gray uppercase tracking-wide">
                                    Total Bookings
                                </p>
                                <p className="text-2xl font-bold text-charcoal mt-1">
                                    {stats?.bookings.total || 0}
                                </p>
                            </div>
                            <div className="w-12 h-12 bg-primary/10 rounded-xl flex items-center justify-center">
                                <Calendar className="w-6 h-6 text-primary" />
                            </div>
                        </div>
                    </CardContent>
                </Card>

                <Card className="border-0 shadow-sm hover:shadow-md transition-shadow">
                    <CardContent className="pt-5 pb-5">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs font-medium text-medium-gray uppercase tracking-wide">Upcoming</p>
                                <p className="text-2xl font-bold text-charcoal mt-1">
                                    {stats?.bookings.upcoming || 0}
                                </p>
                            </div>
                            <div className="w-12 h-12 bg-warning/10 rounded-xl flex items-center justify-center">
                                <Clock className="w-6 h-6 text-warning" />
                            </div>
                        </div>
                    </CardContent>
                </Card>

                <Card className="border-0 shadow-sm hover:shadow-md transition-shadow">
                    <CardContent className="pt-5 pb-5">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs font-medium text-medium-gray uppercase tracking-wide">Completed</p>
                                <p className="text-2xl font-bold text-charcoal mt-1">
                                    {stats?.bookings.completed || 0}
                                </p>
                            </div>
                            <div className="w-12 h-12 bg-success/10 rounded-xl flex items-center justify-center">
                                <CheckCircle className="w-6 h-6 text-success" />
                            </div>
                        </div>
                    </CardContent>
                </Card>

                <Card className="border-0 shadow-sm hover:shadow-md transition-shadow">
                    <CardContent className="pt-5 pb-5">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs font-medium text-medium-gray uppercase tracking-wide">
                                    Notifications
                                </p>
                                <p className="text-2xl font-bold text-charcoal mt-1">
                                    {stats?.notifications.unread || 0}
                                </p>
                            </div>
                            <div className="w-12 h-12 bg-info/10 rounded-xl flex items-center justify-center">
                                <Bell className="w-6 h-6 text-info" />
                            </div>
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* Next Booking Card */}
            {stats?.nextBooking ? (
                <Card className="border-0 shadow-md overflow-hidden">
                    <div className="bg-gradient-to-r from-primary to-accent h-1" />
                    <CardHeader className="pb-2">
                        <div className="flex items-center gap-2">
                            <Sparkles className="w-5 h-5 text-primary" />
                            <CardTitle className="text-lg">Your Next Adventure</CardTitle>
                        </div>
                    </CardHeader>
                    <CardContent>
                        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                            <div className="flex-1">
                                <h3 className="text-xl font-bold text-charcoal mb-2">
                                    {stats.nextBooking.activityTitle}
                                </h3>
                                <div className="flex flex-wrap items-center gap-3 text-sm text-medium-gray">
                                    <span className="flex items-center gap-1.5">
                                        <Calendar className="w-4 h-4 text-primary" />
                                        {new Date(stats.nextBooking.date).toLocaleDateString(
                                            "en-US",
                                            {
                                                weekday: "short",
                                                month: "short",
                                                day: "numeric",
                                            }
                                        )}
                                    </span>
                                    <span className="flex items-center gap-1.5">
                                        <Clock className="w-4 h-4 text-primary" />
                                        {new Date(stats.nextBooking.date).toLocaleTimeString(
                                            "en-US",
                                            {
                                                hour: "2-digit",
                                                minute: "2-digit",
                                            }
                                        )}
                                    </span>
                                </div>
                                <span
                                    className={`inline-block mt-3 px-3 py-1 text-xs font-semibold rounded-full ${stats.nextBooking.status === "CONFIRMED"
                                        ? "bg-success/10 text-success"
                                        : "bg-warning/10 text-warning"
                                        }`}
                                >
                                    {stats.nextBooking.status}
                                </span>
                            </div>
                            <Link href={`/client/bookings/${stats.nextBooking.id}`}>
                                <Button size="lg" className="rounded-full shadow-md shadow-primary/20">
                                    View Details
                                    <ArrowRight className="w-4 h-4 ml-2" />
                                </Button>
                            </Link>
                        </div>
                    </CardContent>
                </Card>
            ) : (
                <Card className="border-0 shadow-md bg-gradient-to-br from-cream to-white">
                    <CardContent className="py-12 text-center">
                        <div className="w-20 h-20 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-4">
                            <Compass className="w-10 h-10 text-primary" />
                        </div>
                        <h3 className="text-xl font-bold text-charcoal mb-2">
                            Ready for your next adventure?
                        </h3>
                        <p className="text-medium-gray mb-6 max-w-md mx-auto">
                            Discover authentic Marrakech experiences - from desert tours to cooking classes.
                        </p>
                        <Link href="/services">
                            <Button size="lg" className="rounded-full shadow-lg shadow-primary/30">
                                <MapPin className="w-4 h-4 mr-2" />
                                Explore Experiences
                            </Button>
                        </Link>
                    </CardContent>
                </Card>
            )}

            {/* Quick Actions */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <Link href="/client/bookings" className="group">
                    <Card className="border-0 shadow-sm hover:shadow-lg hover:border-primary/20 transition-all duration-300 cursor-pointer">
                        <CardContent className="p-5">
                            <div className="flex items-center gap-4">
                                <div className="w-12 h-12 bg-primary/10 rounded-xl flex items-center justify-center group-hover:bg-primary/20 transition-colors">
                                    <Calendar className="w-6 h-6 text-primary" />
                                </div>
                                <div className="flex-1">
                                    <h3 className="font-semibold text-charcoal group-hover:text-primary transition-colors">View All Bookings</h3>
                                    <p className="text-sm text-medium-gray">
                                        Manage your past and upcoming trips
                                    </p>
                                </div>
                                <ArrowRight className="w-5 h-5 text-medium-gray group-hover:text-primary group-hover:translate-x-1 transition-all" />
                            </div>
                        </CardContent>
                    </Card>
                </Link>

                <Link href="/client/messages" className="group">
                    <Card className="border-0 shadow-sm hover:shadow-lg hover:border-primary/20 transition-all duration-300 cursor-pointer">
                        <CardContent className="p-5">
                            <div className="flex items-center gap-4">
                                <div className="w-12 h-12 bg-info/10 rounded-xl flex items-center justify-center group-hover:bg-info/20 transition-colors">
                                    <MessageSquare className="w-6 h-6 text-info" />
                                </div>
                                <div className="flex-1">
                                    <h3 className="font-semibold text-charcoal group-hover:text-primary transition-colors">Contact Support</h3>
                                    <p className="text-sm text-medium-gray">
                                        Get help with your bookings
                                    </p>
                                </div>
                                <ArrowRight className="w-5 h-5 text-medium-gray group-hover:text-primary group-hover:translate-x-1 transition-all" />
                            </div>
                        </CardContent>
                    </Card>
                </Link>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { CreditCard, Download, AlertCircle } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";

interface Payment {
    id: string;
    amount: number;
    currency: string;
    status: string;
    method?: string;
    createdAt: string;
    booking: {
        id: string;
        activityTitle: string;
    };
}

export default function PaymentsPage() {
    const [payments, setPayments] = useState<Payment[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState("all");

    useEffect(() => {
        fetchPayments();
    }, []);

    const fetchPayments = async () => {
        try {
            // Fetch bookings with payment information
            const res = await fetch("/api/bookings");
            if (!res.ok) throw new Error("Failed to fetch payments");
            const data = await res.json();
            // Handle wrapped response
            const bookings = data.data || data;

            // Extract payments from bookings
            const paymentsData: Payment[] = [];
            bookings.forEach((booking: any) => {
                if (booking.payments && booking.payments.length > 0) {
                    booking.payments.forEach((payment: any) => {
                        paymentsData.push({
                            ...payment,
                            booking: {
                                id: booking.id,
                                activityTitle: booking.activityTitle,
                            },
                        });
                    });
                } else if (booking.paymentStatus === "PAID") {
                    // Create a virtual payment record for bookings marked as paid
                    paymentsData.push({
                        id: `virtual-${booking.id}`,
                        amount: booking.totalPrice,
                        currency: "EUR",
                        status: "COMPLETED",
                        method: "UNKNOWN",
                        createdAt: booking.createdAt,
                        booking: {
                            id: booking.id,
                            activityTitle: booking.activityTitle,
                        },
                    });
                }
            });

            setPayments(paymentsData);
        } catch (error) {
            console.error("Error fetching payments:", error);
            toast.error("Failed to load payment history");
        } finally {
            setLoading(false);
        }
    };

    const filterPayments = (filter: string) => {
        switch (filter) {
            case "completed":
                return payments.filter((p) => p.status === "COMPLETED");
            case "pending":
                return payments.filter((p) => p.status === "PENDING");
            case "failed":
                return payments.filter((p) => p.status === "FAILED");
            default:
                return payments;
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case "COMPLETED":
                return "bg-green-100 text-green-800";
            case "PENDING":
                return "bg-yellow-100 text-yellow-800";
            case "FAILED":
                return "bg-red-100 text-red-800";
            default:
                return "bg-gray-100 text-gray-800";
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <div className="text-center">
                    <div className="w-16 h-16 border-4 border-[#FF5F00] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                    <p className="text-gray-600">Loading payment history...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-3xl font-bold text-gray-900">Payment History</h1>
                <p className="text-gray-600 mt-1">
                    View your transaction history and invoices
                </p>
            </div>

            <Tabs value={activeTab} onValueChange={setActiveTab}>
                <TabsList>
                    <TabsTrigger value="all">All ({payments.length})</TabsTrigger>
                    <TabsTrigger value="completed">
                        Completed ({payments.filter((p) => p.status === "COMPLETED").length})
                    </TabsTrigger>
                    <TabsTrigger value="pending">
                        Pending ({payments.filter((p) => p.status === "PENDING").length})
                    </TabsTrigger>
                    <TabsTrigger value="failed">
                        Failed ({payments.filter((p) => p.status === "FAILED").length})
                    </TabsTrigger>
                </TabsList>

                <TabsContent value={activeTab} className="mt-6">
                    {filterPayments(activeTab).length > 0 ? (
                        <Card>
                            <CardContent className="p-0">
                                <Table>
                                    <TableHeader>
                                        <TableRow>
                                            <TableHead>Date</TableHead>
                                            <TableHead>Booking</TableHead>
                                            <TableHead>Amount</TableHead>
                                            <TableHead>Method</TableHead>
                                            <TableHead>Status</TableHead>
                                            <TableHead className="text-right">Actions</TableHead>
                                        </TableRow>
                                    </TableHeader>
                                    <TableBody>
                                        {filterPayments(activeTab).map((payment) => (
                                            <TableRow key={payment.id}>
                                                <TableCell>
                                                    {new Date(payment.createdAt).toLocaleDateString(
                                                        "en-US",
                                                        {
                                                            year: "numeric",
                                                            month: "short",
                                                            day: "numeric",
                                                        }
                                                    )}
                                                </TableCell>
                                                <TableCell>
                                                    <Link
                                                        href={`/client/bookings/${payment.booking.id}`}
                                                        className="text-[#FF5F00] hover:underline"
                                                    >
                                                        {payment.booking.activityTitle}
                                                    </Link>
                                                </TableCell>
                                                <TableCell className="font-medium">
                                                    Γé¼{Number(payment.amount).toFixed(2)}
                                                </TableCell>
                                                <TableCell className="capitalize">
                                                    {payment.method?.toLowerCase() || "N/A"}
                                                </TableCell>
                                                <TableCell>
                                                    <span
                                                        className={`inline-block px-2 py-1 text-xs font-medium rounded ${getStatusColor(
                                                            payment.status
                                                        )}`}
                                                    >
                                                        {payment.status}
                                                    </span>
                                                </TableCell>
                                                <TableCell className="text-right">
                                                    {payment.status === "COMPLETED" && (
                                                        <Button variant="ghost" size="sm">
                                                            <Download className="w-4 h-4 mr-2" />
                                                            Invoice
                                                        </Button>
                                                    )}
                                                </TableCell>
                                            </TableRow>
                                        ))}
                                    </TableBody>
                                </Table>
                            </CardContent>
                        </Card>
                    ) : (
                        <Card>
                            <CardContent className="py-12 text-center">
                                <AlertCircle className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                                <h3 className="text-lg font-semibold text-gray-900 mb-2">
                                    No {activeTab} payments
                                </h3>
                                <p className="text-gray-600">
                                    {activeTab === "all"
                                        ? "You haven't made any payments yet"
                                        : `No ${activeTab} payments to show`}
                                </p>
                            </CardContent>
                        </Card>
                    )}
                </TabsContent>
            </Tabs>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { User, Mail, Phone, Save, Lock } from "lucide-react";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";

interface UserProfile {
    id: string;
    name: string;
    email: string;
    phone?: string;
}

export default function ProfilePage() {
    const [profile, setProfile] = useState<UserProfile | null>(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [formData, setFormData] = useState({
        name: "",
        phone: "",
    });
    const [passwordData, setPasswordData] = useState({
        currentPassword: "",
        newPassword: "",
        confirmPassword: "",
    });
    const [changingPassword, setChangingPassword] = useState(false);
    const [dialogOpen, setDialogOpen] = useState(false);

    useEffect(() => {
        fetchProfile();
    }, []);

    const fetchProfile = async () => {
        try {
            const res = await fetch("/api/user");
            if (!res.ok) throw new Error("Failed to fetch profile");
            const data = await res.json();
            // User API returns direct data, not wrapped
            setProfile(data);
            setFormData({
                name: data.name || "",
                phone: data.phone || "",
            });
        } catch (error) {
            console.error("Error fetching profile:", error);
            toast.error("Failed to load profile");
        } finally {
            setLoading(false);
        }
    };

    const handleSaveProfile = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);
        try {
            const res = await fetch("/api/user", {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(formData),
            });

            if (!res.ok) throw new Error("Failed to update profile");

            toast.success("Profile updated successfully");
            await fetchProfile();
        } catch (error) {
            console.error("Error updating profile:", error);
            toast.error("Failed to update profile");
        } finally {
            setSaving(false);
        }
    };

    const handleChangePassword = async (e: React.FormEvent) => {
        e.preventDefault();

        if (passwordData.newPassword !== passwordData.confirmPassword) {
            toast.error("New passwords don't match");
            return;
        }

        if (passwordData.newPassword.length < 6) {
            toast.error("Password must be at least 6 characters");
            return;
        }

        setChangingPassword(true);
        try {
            const res = await fetch("/api/user/password", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    currentPassword: passwordData.currentPassword,
                    newPassword: passwordData.newPassword,
                }),
            });

            if (!res.ok) {
                const error = await res.json();
                throw new Error(error.error || "Failed to change password");
            }

            toast.success("Password changed successfully");
            setPasswordData({
                currentPassword: "",
                newPassword: "",
                confirmPassword: "",
            });
            setDialogOpen(false);
        } catch (error: any) {
            console.error("Error changing password:", error);
            toast.error(error.message || "Failed to change password");
        } finally {
            setChangingPassword(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <div className="text-center">
                    <div className="w-16 h-16 border-4 border-[#FF5F00] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                    <p className="text-gray-600">Loading profile...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-3xl font-bold text-gray-900">Profile Settings</h1>
                <p className="text-gray-600 mt-1">
                    Manage your account information
                </p>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Profile Picture */}
                <Card>
                    <CardContent className="pt-6">
                        <div className="text-center">
                            <div className="w-24 h-24 bg-[#FF5F00] rounded-full flex items-center justify-center text-white text-3xl font-bold mx-auto mb-4">
                                {profile?.name?.[0]?.toUpperCase() || "U"}
                            </div>
                            <h3 className="font-semibold text-gray-900">{profile?.name}</h3>
                            <p className="text-sm text-gray-600 mt-1">{profile?.email}</p>
                        </div>
                    </CardContent>
                </Card>

                {/* Profile Form */}
                <Card className="lg:col-span-2">
                    <CardHeader>
                        <CardTitle>Personal Information</CardTitle>
                    </CardHeader>
                    <CardContent>
                        <form onSubmit={handleSaveProfile} className="space-y-4">
                            <div>
                                <Label htmlFor="name">Full Name</Label>
                                <div className="relative mt-1">
                                    <User className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                                    <Input
                                        id="name"
                                        value={formData.name}
                                        onChange={(e) =>
                                            setFormData({ ...formData, name: e.target.value })
                                        }
                                        className="pl-10"
                                        required
                                    />
                                </div>
                            </div>

                            <div>
                                <Label htmlFor="email">Email Address</Label>
                                <div className="relative mt-1">
                                    <Mail className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                                    <Input
                                        id="email"
                                        type="email"
                                        value={profile?.email || ""}
                                        className="pl-10 bg-gray-50"
                                        disabled
                                    />
                                </div>
                                <p className="text-xs text-gray-500 mt-1">
                                    Email cannot be changed
                                </p>
                            </div>

                            <div>
                                <Label htmlFor="phone">Phone Number</Label>
                                <div className="relative mt-1">
                                    <Phone className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                                    <Input
                                        id="phone"
                                        type="tel"
                                        value={formData.phone}
                                        onChange={(e) =>
                                            setFormData({ ...formData, phone: e.target.value })
                                        }
                                        className="pl-10"
                                        placeholder="+1 234 567 8900"
                                    />
                                </div>
                            </div>

                            <Button type="submit" disabled={saving}>
                                <Save className="w-4 h-4 mr-2" />
                                {saving ? "Saving..." : "Save Changes"}
                            </Button>
                        </form>
                    </CardContent>
                </Card>
            </div>

            {/* Security Section */}
            <Card>
                <CardHeader>
                    <CardTitle>Security</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="flex items-center justify-between">
                        <div>
                            <h4 className="font-medium text-gray-900">Password</h4>
                            <p className="text-sm text-gray-600">
                                Change your account password
                            </p>
                        </div>
                        <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
                            <DialogTrigger asChild>
                                <Button variant="outline">
                                    <Lock className="w-4 h-4 mr-2" />
                                    Change Password
                                </Button>
                            </DialogTrigger>
                            <DialogContent>
                                <DialogHeader>
                                    <DialogTitle>Change Password</DialogTitle>
                                    <DialogDescription>
                                        Enter your current password and choose a new one
                                    </DialogDescription>
                                </DialogHeader>
                                <form onSubmit={handleChangePassword} className="space-y-4">
                                    <div>
                                        <Label htmlFor="currentPassword">Current Password</Label>
                                        <Input
                                            id="currentPassword"
                                            type="password"
                                            value={passwordData.currentPassword}
                                            onChange={(e) =>
                                                setPasswordData({
                                                    ...passwordData,
                                                    currentPassword: e.target.value,
                                                })
                                            }
                                            required
                                        />
                                    </div>
                                    <div>
                                        <Label htmlFor="newPassword">New Password</Label>
                                        <Input
                                            id="newPassword"
                                            type="password"
                                            value={passwordData.newPassword}
                                            onChange={(e) =>
                                                setPasswordData({
                                                    ...passwordData,
                                                    newPassword: e.target.value,
                                                })
                                            }
                                            required
                                        />
                                    </div>
                                    <div>
                                        <Label htmlFor="confirmPassword">Confirm New Password</Label>
                                        <Input
                                            id="confirmPassword"
                                            type="password"
                                            value={passwordData.confirmPassword}
                                            onChange={(e) =>
                                                setPasswordData({
                                                    ...passwordData,
                                                    confirmPassword: e.target.value,
                                                })
                                            }
                                            required
                                        />
                                    </div>
                                    <Button type="submit" disabled={changingPassword} className="w-full">
                                        {changingPassword ? "Changing..." : "Change Password"}
                                    </Button>
                                </form>
                            </DialogContent>
                        </Dialog>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

