                    host: safeParse(service.host, { name: "Marrakech Host", image: "/localexpert.jpg" }),
                    description: service.description,
                    included: safeParse(service.included, []),
                    exclusions: [],
                    meetingPoint: "",
                    endingPoint: "",
                    cancellationPolicy: "Free cancellation up to 24 hours before the experience",
                    requirements: [],
                    ageRestrictions: "",
                    experienceHighlights: [],
                    additionalInfo: "",
                    minGroupSize: 1,
                    maxGroupSize: 10,
                    whatToBring: safeParse(service.whatToBring, []),
                    itinerary: safeParse(service.itinerary, []),
                    packages: [],
                    packageCategories: [],
                    languages: ["English", "French", "Arabic"],
                };
            });
        } else {
            // Fallback to static activities if database is empty
            activities = staticActivities;
        }
    } catch (error) {
        console.warn("Database connection failed, using static data fallback.", error);
        // Fallback to static activities on error
        activities = staticActivities;
    }

    return <ExperiencesClient initialActivities={activities} />;
}

'use client';

import { useState } from 'react';
import { signIn, useSession } from 'next-auth/react';
import { useRouter, useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { Eye, EyeOff, Lock, Mail, ArrowRight, Loader2, Compass } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Checkbox } from '@/components/ui/checkbox';
import { toast } from 'sonner';

export default function LoginPage() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const callbackUrl = searchParams.get('callbackUrl') || '/client';
    const [isLoading, setIsLoading] = useState(false);
    const [showPassword, setShowPassword] = useState(false);

    // Form state
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);

        try {
            const result = await signIn('credentials', {
                redirect: false,
                email,
                password,
            });

            if (result?.error) {
                toast.error('Invalid email or password');
                return;
            }

            toast.success('Welcome back!');
            
            // Wait a moment for session to update, then check role
            await new Promise(resolve => setTimeout(resolve, 100));
            router.refresh();
            
            // Fetch session to check role
            const sessionRes = await fetch('/api/auth/me');
            const sessionData = await sessionRes.json();
            
            // Redirect based on role
            if (sessionData?.user?.role === 'ADMIN') {
                router.push('/admin/dashboard');
            } else {
                const isSafeCallbackUrl = callbackUrl.startsWith('/') && !callbackUrl.startsWith('//');
                const finalUrl = isSafeCallbackUrl ? callbackUrl : '/client';
                router.push(finalUrl);
            }
        } catch (error) {
            toast.error('Something went wrong. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen grid lg:grid-cols-2">
            {/* Left Side - Form */}
            <div className="flex items-center justify-center p-8 bg-white dark:bg-gray-950">
