                    <div className="absolute inset-0 bg-gradient-to-br from-[#FF5F00]/20 to-[#E55500]/20" />
                </div>
                <div className="relative h-full flex items-center justify-center p-12 text-center">
                    <div className="max-w-xl space-y-6">
