"use client"

import { useState } from "react"
import { toast } from "sonner"
import { Button } from "@/components/ui/button"
import { useRouter } from "next/navigation"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Calendar } from "@/components/ui/calendar"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { format } from "date-fns"
import { CalendarIcon, Loader2, Users } from "lucide-react"
import { cn } from "@/lib/utils"

interface BookingModalProps {
    isOpen: boolean
    onClose: () => void
    serviceTitle: string
    servicePrice: number
    serviceId: string
    onBookingSuccess: () => void
    user?: any
}

export function BookingModal({
    isOpen,
    onClose,
    serviceTitle,
    servicePrice,
    serviceId,
    onBookingSuccess,
    user
}: BookingModalProps) {
    const router = useRouter()
    const [date, setDate] = useState<Date>()
    const [guests, setGuests] = useState(1)
    const [name, setName] = useState(user?.name || "")
    const [email, setEmail] = useState(user?.email || "")
    const [phone, setPhone] = useState("")
    const [loading, setLoading] = useState(false)
    const [error, setError] = useState<string | null>(null)

    const totalPrice = Number(servicePrice) * guests

    const handleBooking = async () => {
        // Validate required fields
        if (!date) {
            setError("Please select a date")
            return
        }

        if (!name || name.trim().length < 2) {
            setError("Please enter your full name (at least 2 characters)")
            return
        }

        // Validate email format
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!email || !emailRegex.test(email)) {
            setError("Please enter a valid email address")
            return
        }

        // Set time to a reasonable default (e.g., 10:00 AM) if not set
        const bookingDate = new Date(date)
        if (bookingDate.getHours() === 0 && bookingDate.getMinutes() === 0) {
            bookingDate.setHours(10, 0, 0, 0) // Default to 10 AM
        }

        // Validate date is in the future
        const now = new Date()
        const oneHourFromNow = new Date(now.getTime() + 60 * 60 * 1000)
        if (bookingDate <= oneHourFromNow) {
            setError("Booking must be at least 1 hour in advance")
            return
        }

        setLoading(true)
        setError(null)

        try {
            const res = await fetch("/api/bookings", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    activityId: serviceId,
                    activityTitle: serviceTitle,
                    date: bookingDate.toISOString(),
                    guests,
                    totalPrice,
                    phone: phone || undefined,
                    name: name.trim(),
                    email: email.trim()
                }),
            })

            if (res.status === 401) {
                const callbackUrl = typeof window !== 'undefined'
                    ? `${window.location.pathname}${window.location.search}`
                    : '/services';
                toast.error('Please log in to book this service.')
                router.push(`/auth/login?callbackUrl=${encodeURIComponent(callbackUrl)}`)
                return
            }

            const data = await res.json()

            if (!res.ok) {
                // Handle structured error response
                let errorMessage = data.error?.message || (typeof data.error === 'string' ? data.error : 'Failed to create booking')

                // If validation error, append details
                if (data.error?.code === 'VALIDATION_ERROR' && Array.isArray(data.error.details)) {
                    const details = data.error.details.map((issue: any) => {
                        const path = issue.path?.join('.') || 'field';
                        return `${path}: ${issue.message}`;
                    }).join(', ');
                    errorMessage = `Validation error: ${details}`;
                } else if (data.error?.code === 'NOT_FOUND') {
                    errorMessage = `Service not found. Please refresh the page and try again.`;
                } else if (data.error?.code === 'BAD_REQUEST') {
                    errorMessage = data.error.message || 'Invalid booking request. Please check your details.';
                }

                throw new Error(errorMessage)
            }

            // Show success message
            toast.success("Thank you! We have received your booking request. We will review it and get back to you as soon as possible.")
            onBookingSuccess()
            onClose()
        } catch (err: any) {
            setError(err.message || "Something went wrong")
        } finally {
            setLoading(false)
        }
    }

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="sm:max-w-[425px]">
                <DialogHeader>
                    <DialogTitle>Book Experience</DialogTitle>
                    <DialogDescription>
                        {serviceTitle}
                    </DialogDescription>
                </DialogHeader>
                <div className="grid gap-4 py-4">
                    {/* Date Picker */}
                    <div className="grid gap-2">
                        <Label>Date</Label>
                        <Popover>
                            <PopoverTrigger asChild>
                                <Button
                                    variant={"outline"}
                                    className={cn(
                                        "w-full justify-start text-left font-normal",
                                        !date && "text-muted-foreground"
                                    )}
                                >
                                    <CalendarIcon className="mr-2 h-4 w-4" />
                                    {date ? format(date, "PPP") : <span>Pick a date</span>}
                                </Button>
                            </PopoverTrigger>
                            <PopoverContent className="w-auto p-0">
                                <Calendar
                                    mode="single"
                                    selected={date}
                                    onSelect={setDate}
                                    initialFocus
                                    disabled={(date) => {
                                        const today = new Date();
                                        today.setHours(0, 0, 0, 0);
                                        const selectedDate = new Date(date);
                                        selectedDate.setHours(0, 0, 0, 0);
                                        return selectedDate < today;
                                    }}
                                />
                            </PopoverContent>
                        </Popover>
                    </div>

                    {/* Guests */}
                    <div className="grid gap-2">
                        <Label>Guests</Label>
                        <div className="flex items-center gap-2">
                            <Users className="h-4 w-4 text-muted-foreground" />
                            <Input
                                type="number"
                                min={1}
                                value={guests}
                                onChange={(e) => setGuests(parseInt(e.target.value) || 1)}
                            />
                        </div>
                    </div>

                    {/* Contact Info (Simple) */}
                    <div className="grid gap-2">
                        <Label>Full Name *</Label>
                        <Input
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            placeholder="Name for reservation"
                            required
                        />
                    </div>
                    <div className="grid gap-2">
                        <Label>Email *</Label>
                        <Input
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="your@email.com"
                            required
                            disabled={!!user?.email}
                        />
                    </div>
                    <div className="grid gap-2">
                        <Label>Phone (Optional)</Label>
                        <Input
                            value={phone}
                            onChange={(e) => setPhone(e.target.value)}
                            placeholder="+1 234 567 890"
                        />
                    </div>

                    {/* Summary */}
                    <div className="bg-muted/50 p-4 rounded-lg mt-2">
                        <div className="flex justify-between font-medium">
                            <span>Total Price</span>
                            <span className="text-primary text-lg">${totalPrice.toFixed(2)}</span>
                        </div>
                    </div>

                    {error && (
                        <p className="text-sm text-red-500 font-medium">{error}</p>
                    )}

                </div>
                <DialogFooter>
                    <Button disabled={loading} onClick={handleBooking} className="w-full">
                        {loading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
                        Confirm Booking
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    )
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "sonner";
import { format } from "date-fns";
import { Calendar as CalendarIcon, Loader2, Save, X } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import { cn } from "@/lib/utils";

interface EditBookingModalProps {
    bookingId: string | null;
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}

export function EditBookingModal({ bookingId, isOpen, onClose, onSuccess }: EditBookingModalProps) {
    const [loading, setLoading] = useState(false);
    const [fetching, setFetching] = useState(false);

    // Form State
    const [date, setDate] = useState<Date | undefined>(undefined);
    const [guests, setGuests] = useState(1);
    const [pickupLocation, setPickupLocation] = useState("");
    const [specialRequests, setSpecialRequests] = useState("");
    const [phone, setPhone] = useState("");

    // Fetch booking details when opened
    useEffect(() => {
        if (isOpen && bookingId) {
            fetchBookingDetails(bookingId);
        }
    }, [isOpen, bookingId]);

    const fetchBookingDetails = async (id: string) => {
        setFetching(true);
        try {
            const res = await fetch(`/api/bookings/${id}`);
            if (!res.ok) throw new Error("Failed to fetch booking");
            const data = await res.json();

            setDate(new Date(data.date));
            setGuests(data.guests);
            setPickupLocation(data.pickupLocation || "");
            setSpecialRequests(data.specialRequests || "");
            setPhone(data.phone || "");
        } catch (error) {
            console.error("Fetch error", error);
            toast.error("Could not load booking details");
            onClose();
        } finally {
            setFetching(false);
        }
    };

    const handleSave = async () => {
        if (!bookingId || !date) return;

        setLoading(true);
        try {
            const res = await fetch(`/api/bookings/${bookingId}`, {
                method: "PATCH",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    date: date.toISOString(),
                    guests,
                    pickupLocation,
                    specialRequests,
                    phone
                })
            });

            if (!res.ok) {
                const err = await res.json();
                throw new Error(err.error || "Update failed");
            }

            toast.success("Booking updated successfully");
            onSuccess();
            onClose();
        } catch (error: any) {
            console.error("Update error", error);
            toast.error(error.message || "Failed to update booking");
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <DialogContent className="sm:max-w-[425px]">
                <DialogHeader>
                    <DialogTitle>Edit Booking</DialogTitle>
                    <DialogDescription>
                        Make changes to your booking here. Click save when you're done.
                    </DialogDescription>
                </DialogHeader>

                {fetching ? (
                    <div className="flex justify-center py-8">
                        <Loader2 className="h-8 w-8 animate-spin text-primary" />
                    </div>
                ) : (
                    <div className="grid gap-4 py-4">
                        {/* Date Picker */}
                        <div className="grid gap-2">
                            <Label htmlFor="date">Date</Label>
                            <Popover>
                                <PopoverTrigger asChild>
                                    <Button
                                        variant={"outline"}
                                        className={cn(
                                            "w-full justify-start text-left font-normal",
                                            !date && "text-muted-foreground"
                                        )}
                                    >
                                        <CalendarIcon className="mr-2 h-4 w-4" />
                                        {date ? format(date, "PPP") : <span>Pick a date</span>}
                                    </Button>
                                </PopoverTrigger>
                                <PopoverContent className="w-auto p-0">
                                    <Calendar
                                        mode="single"
                                        selected={date}
                                        onSelect={setDate}
                                        disabled={(d) => d < new Date()}
                                        initialFocus
                                    />
                                </PopoverContent>
                            </Popover>
                        </div>

                        {/* Guests */}
                        <div className="grid gap-2">
                            <Label htmlFor="guests">Guests</Label>
                            <div className="flex items-center gap-2">
                                <Button
                                    variant="outline" size="sm"
                                    onClick={() => setGuests(Math.max(1, guests - 1))}
                                    type="button"
                                >-</Button>
                                <Input
                                    id="guests"
                                    type="number"
                                    className="text-center"
                                    value={guests}
                                    onChange={(e) => setGuests(parseInt(e.target.value) || 1)}
                                    readOnly
                                />
                                <Button
                                    variant="outline" size="sm"
                                    onClick={() => setGuests(guests + 1)}
                                    type="button"
                                >+</Button>
                            </div>
                        </div>

                        {/* Pickup */}
                        <div className="grid gap-2">
                            <Label htmlFor="pickup">Pickup Location</Label>
                            <Input
                                id="pickup"
                                value={pickupLocation}
                                onChange={(e) => setPickupLocation(e.target.value)}
                            />
                        </div>

                        {/* Phone */}
                        <div className="grid gap-2">
                            <Label htmlFor="phone">Contact Phone</Label>
                            <Input
                                id="phone"
                                value={phone}
                                onChange={(e) => setPhone(e.target.value)}
                            />
                        </div>

                        {/* Requests */}
                        <div className="grid gap-2">
                            <Label htmlFor="requests">Special Requests</Label>
                            <Textarea
                                id="requests"
                                value={specialRequests}
                                onChange={(e) => setSpecialRequests(e.target.value)}
                                className="min-h-[80px]"
                            />
                        </div>
                    </div>
                )}

                <DialogFooter>
                    <Button variant="outline" onClick={onClose} disabled={loading}>
                        Cancel
                    </Button>
                    <Button onClick={handleSave} disabled={loading || fetching}>
                        {loading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Save className="mr-2 h-4 w-4" />}
                        Save Changes
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { Bell, CheckCheck, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Badge } from "@/components/ui/badge";
import { useState } from "react";
import useSWR from "swr";
import { toast } from "sonner";
import Link from "next/link";

interface Notification {
    id: string;
    type: string;
    title: string;
    message: string;
    read: boolean;
    createdAt: string;
    link?: string;
}

const fetcher = (url: string) => fetch(url).then((res) => res.json());

export function Notifications() {
    const [isOpen, setIsOpen] = useState(false);
    const { data, mutate } = useSWR<{ data?: Notification[] } | Notification[]>(
        "/api/notifications",
        fetcher
    );

    const notifications = Array.isArray(data) ? data : data?.data || [];
    const unreadCount = notifications.filter((n) => !n.read).length;

    const handleMarkAsRead = async (id: string) => {
        try {
            const res = await fetch(`/api/notifications/${id}/read`, {
                method: "PATCH",
            });

            if (!res.ok) throw new Error("Failed to mark as read");

            // Optimistically update
            mutate(
                (current) => {
                    if (!current) return current;
                    const notifications = Array.isArray(current) ? current : current.data || [];
                    return Array.isArray(current)
                        ? notifications.map((n) => (n.id === id ? { ...n, read: true } : n))
                        : { ...current, data: notifications.map((n) => (n.id === id ? { ...n, read: true } : n)) };
                },
                false
            );
        } catch (error) {
            console.error("Error marking notification as read:", error);
            toast.error("Failed to update notification");
        }
    };

    const handleMarkAllAsRead = async () => {
        try {
            const unreadIds = notifications.filter((n) => !n.read).map((n) => n.id);
            if (unreadIds.length === 0) return;

            await Promise.all(
                unreadIds.map((id) =>
                    fetch(`/api/notifications/${id}/read`, {
                        method: "PATCH",
                    })
                )
            );

            mutate();
            toast.success("All notifications marked as read");
        } catch (error) {
            console.error("Error marking all as read:", error);
            toast.error("Failed to update notifications");
        }
    };

    const getNotificationIcon = (type: string) => {
        switch (type) {
            case "BOOKING":
            case "BOOKING_CONFIRMED":
                return "bg-green-100 text-green-600";
            case "BOOKING_CANCELLED":
                return "bg-red-100 text-red-600";
            case "ERROR":
                return "bg-red-100 text-red-600";
            case "WARNING":
                return "bg-yellow-100 text-yellow-600";
            default:
                return "bg-blue-100 text-blue-600";
        }
    };

    return (
        <DropdownMenu open={isOpen} onOpenChange={setIsOpen}>
            <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="icon" className="relative">
                    <Bell className="h-5 w-5" />
                    {unreadCount > 0 && (
                        <Badge
                            variant="destructive"
                            className="absolute -top-1 -right-1 h-5 w-5 justify-center rounded-full p-0 text-[10px]"
                        >
                            {unreadCount}
                        </Badge>
                    )}
                </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-80">
                <div className="flex items-center justify-between px-2 py-1.5">
                    <DropdownMenuLabel className="py-0">Notifications</DropdownMenuLabel>
                    {unreadCount > 0 && (
                        <Button
                            variant="ghost"
                            size="sm"
                            className="h-6 px-2 text-xs"
                            onClick={(e) => {
                                e.stopPropagation();
                                handleMarkAllAsRead();
                            }}
                        >
                            <CheckCheck className="h-3 w-3 mr-1" />
                            Mark all as read
                        </Button>
                    )}
                </div>
                <DropdownMenuSeparator />
                <div className="max-h-[300px] overflow-y-auto">
                    {notifications.length === 0 ? (
                        <div className="px-2 py-6 text-center text-sm text-muted-foreground">
                            No notifications
                        </div>
                    ) : (
                        notifications.slice(0, 5).map((notification) => {
                            const notificationContent = (
                                <>
                                    <div
                                        className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${getNotificationIcon(
                                            notification.type
                                        )}`}
                                    >
                                        <Bell className="w-4 h-4" />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <p
                                            className={`text-sm font-medium ${!notification.read ? "text-gray-900" : "text-gray-600"
                                                }`}
                                        >
                                            {notification.title}
                                        </p>
                                        <p className="text-xs text-gray-500 mt-0.5 line-clamp-2">
                                            {notification.message}
                                        </p>
                                        <p className="text-xs text-gray-400 mt-1">
                                            {new Date(notification.createdAt).toLocaleDateString("en-US", {
                                                month: "short",
                                                day: "numeric",
                                                hour: "2-digit",
                                                minute: "2-digit",
                                            })}
                                        </p>
                                    </div>
                                    {!notification.read && (
                                        <div className="w-2 h-2 rounded-full bg-[#FF5F00] flex-shrink-0 mt-2" />
                                    )}
                                </>
                            );

                            return (
                                <DropdownMenuItem
                                    key={notification.id}
                                    className="flex items-start gap-3 px-3 py-2.5 cursor-pointer"
                                    onClick={() => {
                                        if (!notification.read) {
                                            handleMarkAsRead(notification.id);
                                        }
                                        if (notification.link) {
                                            setIsOpen(false);
                                        }
                                    }}
                                    asChild={notification.link ? true : undefined}
                                >
                                    {notification.link ? (
                                        <Link href={notification.link} className="flex items-start gap-3 w-full">
                                            {notificationContent}
                                        </Link>
                                    ) : (
                                        <div className="flex items-start gap-3 w-full">
                                            {notificationContent}
                                        </div>
                                    )}
                                </DropdownMenuItem>
                            );
                        })
                    )}
                </div>
                {notifications.length > 5 && (
                    <>
                        <DropdownMenuSeparator />
                        <div className="px-2 py-1.5">
                            <Link href="/client/notifications">
                                <Button
                                    variant="ghost"
                                    className="w-full text-xs"
                                    onClick={() => setIsOpen(false)}
                                >
                                    View all notifications
                                </Button>
                            </Link>
                        </div>
                    </>
                )}
            </DropdownMenuContent>
        </DropdownMenu>
    );
}

