"use client";

interface RatingBubbleProps {
    rating: number;
    size?: "sm" | "md" | "lg";
    showNumber?: boolean;
}

export function RatingBubble({ rating, size = "md", showNumber = true }: RatingBubbleProps) {
    // Ensure rating is valid
    const safeRating = Math.max(0, Math.min(5, rating || 0));
    const fullCircles = Math.floor(safeRating);
    const hasHalfCircle = safeRating % 1 >= 0.5;
    const emptyCircles = 5 - fullCircles - (hasHalfCircle ? 1 : 0);

    return (
        <div className="flex items-center gap-0.5" title={`${safeRating.toFixed(1)} of 5 bubbles`}>
            {[...Array(fullCircles)].map((_, i) => (
                <div key={`full-${i}`} className={`rounded-full bg-[#FF5F00] ${size === "sm" ? "w-3 h-3" : "w-4 h-4"} border border-[#FF5F00]`} />
            ))}
            {hasHalfCircle && (
                <div className={`rounded-full relative overflow-hidden bg-white border border-[#FF5F00] ${size === "sm" ? "w-3 h-3" : "w-4 h-4"}`}>
                    <div className="absolute top-0 left-0 h-full w-1/2 bg-[#FF5F00]" />
                </div>
            )}
            {[...Array(emptyCircles)].map((_, i) => (
                <div key={`empty-${i}`} className={`rounded-full bg-white border border-[#FF5F00] ${size === "sm" ? "w-3 h-3" : "w-4 h-4"}`} />
            ))}
        </div>
    );
}

// Review quality labels based on rating
export function getReviewLabel(rating: number): string {
    if (rating >= 5.0) return "Excellent";
    if (rating >= 4.5) return "Very Good";
    if (rating >= 4.0) return "Good";
    if (rating >= 3.0) return "Average";
    if (rating >= 2.0) return "Poor";
    return "Terrible";
}

/**
 * Standardized API Response Helpers
 * Provides consistent response formatting across all API routes
 */

import { NextResponse } from 'next/server';
import { formatErrorResponse, isAppError } from './errors';

function serializeDecimals(value: unknown): unknown {
    if (value === null || value === undefined) return value;

    if (typeof value === 'object') {
        if (value && 'toNumber' in value && typeof (value as any).toNumber === 'function') {
            return (value as any).toNumber();
        }

        if (Array.isArray(value)) {
            return value.map(serializeDecimals);
        }

        const obj = value as Record<string, unknown>;
        const out: Record<string, unknown> = {};
        for (const [k, v] of Object.entries(obj)) {
            out[k] = serializeDecimals(v);
        }
        return out;
    }

    return value;
}

/**
 * Success response with data
 */
export function successResponse<T>(data: T, statusCode = 200) {
    return NextResponse.json(serializeDecimals(data), { status: statusCode });
}

/**
 * Created response (201)
 */
export function createdResponse<T>(data: T) {
    return successResponse(data, 201);
}

/**
 * No content response (204)
 */
export function noContentResponse() {
    return new NextResponse(null, { status: 204 });
}

/**
 * Error response
 */
export function errorResponse(error: unknown) {
    const { statusCode, body } = formatErrorResponse(error);

    // Log error for monitoring (exclude validation errors)
    if (statusCode >= 500) {
        console.error('[API Error]', {
            statusCode,
            error: error instanceof Error ? error.message : 'Unknown error',
            stack: error instanceof Error ? error.stack : undefined,
        });
    }

    return NextResponse.json(body, { status: statusCode });
}

/**
 * Wrap async API handler with error handling
 */
export function withErrorHandling<T extends (...args: any[]) => Promise<NextResponse>>(
    handler: T
): T {
    return (async (...args: Parameters<T>) => {
        try {
            return await handler(...args);
        } catch (error) {
            return errorResponse(error);
        }
    }) as T;
}

/**
 * Paginated response helper
 */
export interface PaginationMeta {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
    hasNext: boolean;
    hasPrev: boolean;
}

export interface PaginatedResponse<T> {
    data: T[];
    pagination: PaginationMeta;
}

export function paginatedResponse<T>(
    data: T[],
    page: number,
    limit: number,
    total: number
) {
    const totalPages = Math.ceil(total / limit);

    const response: PaginatedResponse<T> = {
        data,
        pagination: {
            page,
            limit,
            total,
            totalPages,
            hasNext: page < totalPages,
            hasPrev: page > 1,
        },
    };

    return successResponse(response);
}

import { SignJWT, jwtVerify } from 'jose';
import bcrypt from 'bcryptjs';

/**
 * Authentication Utilities
 * 
 * IMPORTANT: This module provides low-level authentication utilities.
 * For user authentication, use NextAuth v5 (see @/auth.ts).
 * 
 * These utilities are for:
 * - Password hashing (used by NextAuth and user registration)
 * - JWT signing/verification (for potential API tokens or custom integrations)
 */

// JWT Secret - validate at runtime when needed, not at build time
const RAW_JWT_SECRET = process.env.JWT_SECRET || '';

function getEncodedJWTSecret(): Uint8Array {
    if (!RAW_JWT_SECRET) {
        throw new Error('Γ¥î JWT_SECRET environment variable is required but not set.\nGenerate one with: openssl rand -base64 32');
    }
    return new TextEncoder().encode(RAW_JWT_SECRET);
}

/**
 * Hash password with bcrypt (12 rounds for production-grade security)
 */
export async function hashPassword(password: string): Promise<string> {
    return await bcrypt.hash(password, 12);
}

/**
 * Compare plain password with hashed password
 */
export async function comparePassword(plain: string, hashed: string): Promise<boolean> {
    return await bcrypt.compare(plain, hashed);
}

export interface UserPayload {
    id: string;
    email: string;
    role: string;
    name?: string | null;
    [key: string]: unknown;
}

/**
 * Sign JWT token with 1 hour expiration
 * Use for API tokens or custom integrations, NOT for session management (use NextAuth)
 */
export async function signJWT(payload: UserPayload): Promise<string> {
    return new SignJWT(payload)
        .setProtectedHeader({ alg: 'HS256' })
        .setIssuedAt()
        .setExpirationTime('1h')
        .sign(getEncodedJWTSecret());
}

/**
 * Verify JWT token
 * Use for API tokens or custom integrations, NOT for session management (use NextAuth)
 */
export async function verifyJWT(token: string): Promise<UserPayload> {
    try {
        const { payload } = await jwtVerify(token, getEncodedJWTSecret());
        return payload as UserPayload;
    } catch (error) {
        throw new Error('Invalid or expired token');
    }
}

