// Service Schemas
export const createServiceSchema = z.object({
    title: z.string().min(3, 'Title is required'),
    description: z.string().min(10, 'Description is required'),
    price: z.number().min(0, 'Price must be positive'),
    category: z.string().min(1, 'Category is required'),
    duration: z.string().optional().default('TBD'),
    location: z.string().optional().default('Marrakech'),
    latitude: z.number().optional().default(0),
    longitude: z.number().optional().default(0),
    images: z.array(z.string()).optional().default([]),
    features: z.array(z.string()).optional().default([]),
    included: z.array(z.string()).optional().default([]),
    excluded: z.array(z.string()).optional().default([]),
    whatToBring: z.array(z.string()).optional().default([]),
    highlights: z.array(z.string()).optional().default([]),
    tags: z.array(z.string()).optional().default([]),
    itinerary: z.array(z.object({
        time: z.string().min(1),
        title: z.string().min(1),
        description: z.string().min(1),
    })).optional().default([]),
    host: z.string().optional().default('Explore Marrakesh'),
});

export const updateServiceSchema = createServiceSchema.partial();

// Booking Schemas
export const createBookingSchema = z.object({
    activityId: z.string().min(1, 'Invalid Activity ID'),
    activityTitle: z.string().min(1, 'Activity Title is required'),
    date: z.string().datetime().transform((str) => new Date(str)), // Coerce string to Date
    guests: z.coerce.number().int().min(1).max(50),
    totalPrice: z.coerce.number().positive(),
    pickupLocation: z.string().optional(),
    phone: z.string().optional(),
    name: z.string().min(2, 'Name is required'),
    email: z.string().email('Invalid email address'),
    flightNumber: z.string().optional(),
    language: z.string().optional(),
    dietary: z.string().optional(),
    specialRequests: z.string().optional(),
    packageName: z.string().optional(),
});

export const updateBookingSchema = z.object({
    date: z.string().datetime().transform((str) => new Date(str)).optional(),
    guests: z.coerce.number().int().min(1).max(50).optional(),
    pickupLocation: z.string().optional(),
    phone: z.string().optional(),
    specialRequests: z.string().optional(),
});

// User/Auth Schemas
export const loginSchema = z.object({
    email: z.string().email(),
    password: z.string().min(6),
});

export const registerSchema = z.object({
    name: z.string().min(2),
    email: z.string().email(),
    password: z.string().min(6),
    role: userRoleSchema.optional().default('CUSTOMER'),
});

// Payment Schemas
export const createPaymentSchema = z.object({
    bookingId: bookingIdSchema,
    amount: z.coerce.number().positive('Amount must be positive'),
    currency: z.nativeEnum(PaymentCurrency).optional().default(PaymentCurrency.EUR),
    method: z.nativeEnum(PaymentMethod).optional(),
});

export const processPaymentSchema = z.object({
    paymentId: z.string().uuid('Invalid Payment ID'),
    transactionId: z.string().optional(),
});

// Review Schemas
export const createReviewSchema = z.object({
    bookingId: bookingIdSchema,
    serviceId: serviceIdSchema,
    rating: z.coerce.number().int().min(1).max(5, 'Rating must be between 1 and 5'),
    comment: z.string().min(10, 'Review comment must be at least 10 characters'),
});

export const updateReviewSchema = z.object({
    rating: z.coerce.number().int().min(1).max(5).optional(),
    comment: z.string().min(10).optional(),
});

// User Profile Schemas
export const updateUserSchema = z.object({
    name: z.string().min(2).optional(),
    email: z.string().email().optional(),
    phone: z.string().optional(),
});

export const changePasswordSchema = z.object({
    currentPassword: z.string().min(1, 'Current password is required'),
    newPassword: z.string().min(6, 'New password must be at least 6 characters'),
});

export const updateUserRoleSchema = z.object({
    role: userRoleSchema,
});

// Notification Schemas
export const createNotificationSchema = z.object({
    userId: z.string().uuid('Invalid User ID'),
    title: z.string().min(1, 'Title is required'),
    message: z.string().min(1, 'Message is required'),
    type: z.enum(['INFO', 'SUCCESS', 'WARNING', 'ERROR', 'BOOKING', 'REVIEW']).optional(),
    link: z.string().optional(),
});

// Pagination Schema
export const paginationSchema = z.object({
    page: z.coerce.number().int().min(1).optional().default(1),
    limit: z.coerce.number().int().min(1).max(100).optional().default(10),
    sortBy: z.string().optional(),
    sortOrder: z.enum(['asc', 'desc']).optional().default('desc'),
});

// Support Request Schema
export const createSupportRequestSchema = z.object({
    name: z.string().min(2, 'Name is required'),
    email: z.string().email('Invalid email address'),
    phone: z.string().optional(),
    subject: z.string().min(3, 'Subject is required'),
    message: z.string().min(10, 'Message must be at least 10 characters'),
});

/**
 * Admin Service
 * Contains all business logic for admin operations and dashboard
 */

import { bookingRepository } from '@/repositories/booking.repository';
import { userRepository } from '@/repositories/user.repository';
import { serviceRepository } from '@/repositories/service.repository';
import { paymentRepository } from '@/repositories/payment.repository';
import { reviewRepository } from '@/repositories/review.repository';
import { supportRepository } from '@/repositories/support.repository';
import { decimalToNumber } from '@/lib/decimal';

export interface DashboardStats {
    overview: {
        totalBookings: number;
        totalRevenue: number;
        totalUsers: number;
        totalServices: number;
    };
    bookings: {
        pending: number;
        confirmed: number;
        completed: number;
        cancelled: number;
    };
    revenue: {
        total: number;
        thisMonth: number;
        lastMonth: number;
        growth: number; // percentage
    };
    users: {
        total: number;
        active: number;
        new: number; // last 30 days
    };
    recent: {
        bookings: any[];
        reviews: any[];
        supportRequests: any[];
    };
}

export interface RevenueAnalytics {
    total: number;
    byMonth: { month: string; revenue: number }[];
    byService: { serviceId: string; title: string; revenue: number }[];
    topServices: { serviceId: string; title: string; bookings: number; revenue: number }[];
}

export class AdminService {
    /**
     * Get comprehensive dashboard statistics
     */
    async getDashboardStats(): Promise<DashboardStats> {
        const now = new Date();
        const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        const thisMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);
        const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
        const lastMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);

        // Get overview stats
        const [totalBookings, totalRevenue, totalUsers, totalServices] = await Promise.all([
            bookingRepository.count(),
            paymentRepository.getSuccessfulPaymentsTotal(),
            userRepository.count(),
            serviceRepository.count()
        ]);

        // Get booking stats by status
        const [pending, confirmed, completed, cancelled] = await Promise.all([
            bookingRepository.countByStatus('PENDING'),
            bookingRepository.countByStatus('CONFIRMED'),
            bookingRepository.countByStatus('COMPLETED'),
            bookingRepository.countByStatus('CANCELLED')
        ]);

        // Get revenue stats
        const thisMonthRevenue = await bookingRepository.getTotalRevenue({
            createdAt: { gte: thisMonthStart },
            status: 'COMPLETED'
        });

        const lastMonthRevenue = await bookingRepository.getTotalRevenue({
            createdAt: { gte: lastMonthStart, lte: lastMonthEnd },
            status: 'COMPLETED'
        });

        const revenueGrowth = lastMonthRevenue > 0
            ? ((thisMonthRevenue - lastMonthRevenue) / lastMonthRevenue) * 100
            : 0;

        // Get user stats
        const activeUsers = await userRepository.findActiveUsers(30);
        const newUsers = await userRepository.count({
            createdAt: { gte: thirtyDaysAgo }
        });

        // Get recent data
        const [recentBookings, recentReviews, recentSupport] = await Promise.all([
            bookingRepository.findRecent(5),
            reviewRepository.findRecent(5),
            supportRepository.findRecent(5)
        ]);

        return {
            overview: {
                totalBookings,
                totalRevenue,
                totalUsers,
                totalServices
            },
            bookings: {
                pending,
                confirmed,
                completed,
                cancelled
            },
            revenue: {
                total: totalRevenue,
                thisMonth: thisMonthRevenue,
                lastMonth: lastMonthRevenue,
                growth: Math.round(revenueGrowth * 100) / 100
            },
            users: {
                total: totalUsers,
                active: activeUsers.length,
                new: newUsers
            },
            recent: {
                bookings: recentBookings,
                reviews: recentReviews,
                supportRequests: recentSupport
            }
        };
    }

    /**
     * Get revenue analytics
     */
    async getRevenueAnalytics(): Promise<RevenueAnalytics> {
        // Get total revenue
        const total = await paymentRepository.getSuccessfulPaymentsTotal();

        // Get all completed bookings for analysis
        const completedBookings = await bookingRepository.findMany({
            where: { status: 'COMPLETED' }
        });

        // Calculate revenue by month
        const byMonth: Record<string, number> = {};
        const byService: Record<string, { title: string; revenue: number }> = {};

        completedBookings.forEach(booking => {
            // By month
            const monthKey = booking.createdAt.toISOString().slice(0, 7); // YYYY-MM
            byMonth[monthKey] = (byMonth[monthKey] || 0) + decimalToNumber(booking.totalPrice);

            // By service
            if (!byService[booking.activityId]) {
                byService[booking.activityId] = {
                    title: booking.activityTitle,
                    revenue: 0
                };
            }
            byService[booking.activityId].revenue += decimalToNumber(booking.totalPrice);
        });

        // Convert to arrays and sort
        const byMonthArray = Object.entries(byMonth)
            .map(([month, revenue]) => ({ month, revenue }))
            .sort((a, b) => a.month.localeCompare(b.month));

        const byServiceArray = Object.entries(byService)
            .map(([serviceId, data]) => ({
                serviceId,
                title: data.title,
                revenue: data.revenue
            }))
            .sort((a, b) => b.revenue - a.revenue);

        // Get top services by bookings and revenue
        const serviceBookingCounts: Record<string, { title: string; count: number; revenue: number }> = {};
        completedBookings.forEach(booking => {
            if (!serviceBookingCounts[booking.activityId]) {
                serviceBookingCounts[booking.activityId] = {
                    title: booking.activityTitle,
                    count: 0,
                    revenue: 0
                };
            }
            serviceBookingCounts[booking.activityId].count++;
            serviceBookingCounts[booking.activityId].revenue += decimalToNumber(booking.totalPrice);
        });

        const topServices = Object.entries(serviceBookingCounts)
            .map(([serviceId, data]) => ({
                serviceId,
                title: data.title,
                bookings: data.count,
                revenue: data.revenue
            }))
            .sort((a, b) => b.revenue - a.revenue)
            .slice(0, 10);

        return {
            total,
            byMonth: byMonthArray,
            byService: byServiceArray,
            topServices
        };
    }

    /**
     * Get booking analytics
     */
    async getBookingAnalytics() {
        const totalBookings = await bookingRepository.count();
        const bookingsByStatus = {
            pending: await bookingRepository.countByStatus('PENDING'),
            confirmed: await bookingRepository.countByStatus('CONFIRMED'),
            completed: await bookingRepository.countByStatus('COMPLETED'),
            cancelled: await bookingRepository.countByStatus('CANCELLED')
        };

        const averageBookingValue = await bookingRepository.getTotalRevenue() / (totalBookings || 1);

        return {
            total: totalBookings,
            byStatus: bookingsByStatus,
            averageValue: Math.round(averageBookingValue * 100) / 100
        };
    }

    /**
     * Get user analytics
     */
    async getUserAnalytics() {
        const totalUsers = await userRepository.count();
        const customerCount = await userRepository.count({ role: 'CUSTOMER' });
        const adminCount = await userRepository.count({ role: 'ADMIN' });
        const activeUsers = await userRepository.findActiveUsers(30);

        const now = new Date();
        const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        const newUsers = await userRepository.count({
            createdAt: { gte: thirtyDaysAgo }
        });

        return {
            total: totalUsers,
            byRole: {
                customers: customerCount,
                admins: adminCount
            },
            active: activeUsers.length,
            new: newUsers
        };
    }

    /**
     * Get support request statistics
     */
    async getSupportStats() {
        return await supportRepository.getStats();
    }

    /**
     * Get system health metrics
     */
    async getSystemHealth() {
        const [
            pendingBookings,
            pendingSupport,
            failedPayments
        ] = await Promise.all([
            bookingRepository.countByStatus('PENDING'),
            supportRepository.countByStatus('PENDING'),
            paymentRepository.count({ status: 'FAILED' })
        ]);

        return {
            pendingBookings,
            pendingSupport,
            failedPayments,
            requiresAttention: pendingSupport > 5 || failedPayments > 3
        };
    }
    /**
     * Get admin alerts (legacy support + new logic)
     */
    async getAdminAlerts() {
        const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000);

        // Unconfirmed bookings > 24h
        const unconfirmed = await bookingRepository.findMany({
            where: {
                status: 'PENDING',
                createdAt: { lt: yesterday }
            }
        });

        const alerts: any[] = [];

        unconfirmed.forEach(b => {
            alerts.push({
                id: `booking-${b.id}`,
                type: 'WARNING',
                title: `Unconfirmed Booking: ${b.name}`,
                time: '24h+',
                action: 'Review',
                rawDate: b.createdAt
            });
        });

        // Mock critical alert for demo (preserving legacy behavior)
        alerts.push({
            id: 'mock-1',
            type: 'CRITICAL',
            title: 'Payment Failed: Booking #B-998',
            time: '12m ago',
            action: 'Retry',
            rawDate: new Date(Date.now() - 12 * 60 * 1000)
        });

        return alerts.sort((a, b) => b.rawDate.getTime() - a.rawDate.getTime());
    }

    /**
     * Get urgent stats
     */
    async getUrgentStats() {
        const [pendingBookings, pendingSupport] = await Promise.all([
            bookingRepository.countByStatus('PENDING'),
            supportRepository.countByStatus('PENDING') // Support uses PENDING string default
        ]);

        return {
            pendingBookings,
            pendingSupport,
            pendingReviews: 0 // Placeholder
        };
    }

    /**
     * Get top services
     */
    async getTopServices() {
        const analytics = await this.getRevenueAnalytics();
        return analytics.topServices.map(s => ({
            id: s.serviceId,
            title: s.title,
            bookingsCount: s.bookings,
            revenue: s.revenue,
            rating: 4.8 // Mock or fetch real rating if needed
        })).slice(0, 5);
    }
    /**
     * Get legacy/daily stats for dashboard
     */
    async getDailyStats() {
        // Calculate today's range
        const now = new Date();
        const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate());

        // Get today's bookings
        const bookingsToday = await bookingRepository.count({
            createdAt: { gte: startOfDay }
        });

        // Get today's revenue (only from confirmed/completed/paid bookings ideally, but for simplicity use total)
        // Better: use paymentRepository for revenue, but booking.totalPrice is used in legacy
        const revenueToday = await bookingRepository.getTotalRevenue({
            createdAt: { gte: startOfDay },
            status: { not: 'CANCELLED' } // Approximate
        });

        // Get active users (logged in recently or created recently)
        const activeUsersCount = (await userRepository.findActiveUsers(7)).length;

        // Calculate conversion rate (Total Bookings / Total Users) * 100
        const totalUsers = await userRepository.count();
        const totalBookings = await bookingRepository.count();
        const conversionRate = totalUsers > 0 ? (totalBookings / totalUsers) * 100 : 0;

        return {
            revenueToday,
            bookingsToday,
            activeUsers: activeUsersCount,
            conversionRate: Math.round(conversionRate * 10) / 10
        };
    }
}

// Export singleton instance
export const adminService = new AdminService();

/**
 * Booking Service
 * Contains all business logic for booking operations
 */

import { Booking, BookingStatus, PaymentStatus } from '@prisma/client';
import { bookingRepository } from '@/repositories/booking.repository';
import { serviceRepository } from '@/repositories/service.repository';
import { notificationService } from '@/services/notification.service';
import { generateShortId, ShortIdPrefix } from '@/lib/id-generator';
import { NotFoundError, BadRequestError } from '@/lib/errors';
import { createBookingSchema } from '@/lib/validation';

export interface CreateBookingDTO {
    activityId: string;
    activityTitle: string;
    date: Date;
    guests: number;
    totalPrice: number;
    pickupLocation?: string;
    phone?: string;
    name: string;
    email: string;
    flightNumber?: string;
    language?: string;
    dietary?: string;
    specialRequests?: string;
    packageName?: string;
}

export interface UpdateBookingDTO {
    date?: Date;
    guests?: number;
    pickupLocation?: string;
    phone?: string;
    specialRequests?: string;
}

export interface BookingStats {
    total: number;
    upcoming: number;
    completed: number;
    cancelled: number;
    pending: number;
    totalRevenue: number;
}

export class BookingService {
    /**
     * Create a new booking
     */
    async createBooking(data: CreateBookingDTO, userId: string): Promise<Booking> {
        // Validate activity exists by ID first
        let activityExists = await serviceRepository.exists(data.activityId);
        let actualActivityId = data.activityId;

        // If not found by ID, try to find by title (fallback for static activities)
        if (!activityExists) {
            console.warn(`Activity with ID ${data.activityId} not found. Trying to find by title: ${data.activityTitle}`);
            const serviceByTitle = await serviceRepository.findByTitle(data.activityTitle);
            if (serviceByTitle) {
                actualActivityId = serviceByTitle.id;
                activityExists = true;
                console.log(`Found activity by title. Using database ID: ${actualActivityId}`);
            }
        }

        // If still not found, try one more time with case-insensitive title search
        // and also try partial matching
        if (!activityExists) {
            // Try case-insensitive search again (in case findByTitle didn't work)
            const allServices = await serviceRepository.findMany({});
            const matchingService = allServices.find(s =>
                s.title.toLowerCase().trim() === data.activityTitle.toLowerCase().trim() ||
                s.title.toLowerCase().includes(data.activityTitle.toLowerCase()) ||
                data.activityTitle.toLowerCase().includes(s.title.toLowerCase())
            );

            if (matchingService) {
                actualActivityId = matchingService.id;
                activityExists = true;
                console.log(`Found service by fuzzy title match. Using database ID: ${actualActivityId}`);
            }
        }

        // If still not found, create the service automatically from booking data
        // This ensures bookings always work even if the service wasn't pre-created
        if (!activityExists) {
            console.log(`Service not found. Creating service automatically from booking data: ${data.activityTitle}`);
            try {
                const { generateShortId, ShortIdPrefix } = await import('@/lib/id-generator');

                // Check one more time if service was created by another concurrent request
                const doubleCheck = await serviceRepository.findByTitle(data.activityTitle);
                if (doubleCheck) {
                    actualActivityId = doubleCheck.id;
                    activityExists = true;
                    console.log(`Service found after double-check. Using database ID: ${actualActivityId}`);
                } else {
                    const newService = await serviceRepository.create({
                        id: generateShortId(ShortIdPrefix.SERVICE),
                        title: data.activityTitle,
                        description: `Service created from booking: ${data.activityTitle}`,
                        price: data.totalPrice / data.guests, // Calculate price per person
                        category: 'Experience', // Default category
                        duration: 'TBD',
                        location: 'Marrakech',
                        images: [],
                        features: [],
                        included: [],
                        whatToBring: [],
                        tags: [],
                        itinerary: [],
                        host: 'Explore Marrakesh',
                        rating: 0,
                        reviews: 0,
                    });

                    actualActivityId = newService.id;
                    activityExists = true;
                    console.log(`Created new service with ID: ${actualActivityId}`);
                }
            } catch (error) {
                console.error('Failed to create service automatically:', error);
                // If creation fails, try one last time to find by title (case-insensitive)
                const lastAttempt = await serviceRepository.findByTitle(data.activityTitle);
                if (lastAttempt) {
                    actualActivityId = lastAttempt.id;
                    activityExists = true;
                } else {
                    // Final fallback: throw a user-friendly error
                    throw new NotFoundError(
                        'Activity',
                        data.activityId,
                        `Unable to process booking for "${data.activityTitle}". Please try again or contact support.`
                    );
                }
            }
        }

        // Validate booking date is in the future
        // Compare dates properly - allow same day if time is in the future
        const now = new Date();
        const bookingDate = new Date(data.date);

        // If booking is for today, check if time is in the future
        if (bookingDate.toDateString() === now.toDateString()) {
            // Same day - check if time is in the future (at least 1 hour ahead)
            const oneHourFromNow = new Date(now.getTime() + 60 * 60 * 1000);
            if (bookingDate <= oneHourFromNow) {
                throw new BadRequestError('Booking must be at least 1 hour in advance');
            }
        } else if (bookingDate <= now) {
            // Past date
            throw new BadRequestError('Booking date must be in the future');
        }

        // Validate guests count
        if (data.guests < 1 || data.guests > 50) {
            throw new BadRequestError('Number of guests must be between 1 and 50');
        }

        // Validate price
        if (data.totalPrice <= 0 || data.totalPrice > 100000) {
            throw new BadRequestError('Invalid price value');
        }

        // Create booking (use actualActivityId if we found it by title)
        const booking = await bookingRepository.create({
            id: generateShortId(ShortIdPrefix.BOOKING),
            userId,
            name: data.name,
            email: data.email,
            phone: data.phone || null,
            activityId: actualActivityId, // Use the actual database ID
            activityTitle: data.activityTitle,
            date: data.date,
            guests: data.guests,
            totalPrice: data.totalPrice,
            pickupLocation: data.pickupLocation || null,
            flightNumber: data.flightNumber || null,
            language: data.language || null,
            dietary: data.dietary || null,
            specialRequests: data.specialRequests || null,
            packageName: data.packageName || null,
            status: BookingStatus.PENDING,
            paymentStatus: PaymentStatus.UNPAID
        });

        // Send notification to user if they have an account
        if (userId) {
            try {
                await notificationService.sendBookingConfirmation(
                    userId,
                    booking.id,
                    data.activityTitle
                );
            } catch (error) {
                // Don't fail booking creation if notification fails
                console.error('Failed to send booking confirmation notification:', error);
            }
        }

        // Send booking received email (for both logged-in and guest users)
        // This is NOT a confirmation - just acknowledging receipt of the booking request
        try {
            const { emailService } = await import('@/services/email.service');
            await emailService.sendBookingReceived(
                data.email,
                data.name,
                booking.id,
                data.activityTitle,
                data.date,
                data.guests,
                data.totalPrice
            );

            await emailService.sendAdminBookingNotification(
                booking.id,
                data.activityTitle,
                data.date,
                data.guests,
                data.totalPrice,
                data.name,
                data.email
            );
        } catch (error) {
            // Don't fail booking creation if email fails
            console.error('Failed to send booking received email:', error);
        }

        return booking;
    }

    /**
     * Get booking by ID
     */
    async getBookingById(id: string, userId?: string): Promise<Booking> {
        const booking = await bookingRepository.findById(id);

        if (!booking) {
            throw new NotFoundError('Booking', id);
        }

        // If userId provided, verify ownership (admins bypass this in the route)
        if (userId && booking.userId !== userId) {
            throw new NotFoundError('Booking', id); // Don't reveal existence
        }

        return booking;
    }

    /**
     * Get all bookings for a user
     */
    async getUserBookings(userId: string): Promise<Booking[]> {
        return await bookingRepository.findByUserId(userId);
    }

    /**
     * Get all bookings (admin only)
     */
    async getAllBookings(): Promise<Booking[]> {
        return await bookingRepository.findMany({
            orderBy: { createdAt: 'desc' },
            include: {
                user: {
                    select: {
                        id: true,
                        name: true,
                        email: true,
                    }
                }
            }
        });
    }

    /**
     * Update booking status
     */
    async updateBookingStatus(id: string, status: BookingStatus): Promise<Booking> {
        // Validate booking exists
        const booking = await bookingRepository.findById(id);
        if (!booking) {
            throw new NotFoundError('Booking', id);
        }

        // Validate status transition
        this.validateStatusTransition(booking.status, status);

        // Update status
        const updatedBooking = await bookingRepository.updateStatus(id, status);

        // Send notification to user if they have an account
        if (booking.userId) {
            try {
                await notificationService.sendBookingStatusUpdate(
                    booking.userId,
                    booking.id,
                    booking.activityTitle,
                    status
                );
            } catch (error) {
                // Don't fail status update if notification fails
                console.error('Failed to send status update notification:', error);
            }
        }

        return updatedBooking;
    }

    /**
     * Cancel booking
     */
    async cancelBooking(id: string, userId: string): Promise<Booking> {
        const booking = await bookingRepository.findById(id);

        if (!booking) {
            throw new NotFoundError('Booking', id);
        }

        // Verify ownership
        if (booking.userId !== userId) {
            throw new NotFoundError('Booking', id);
        }

        // Check if booking can be cancelled
        if (booking.status === BookingStatus.COMPLETED || booking.status === BookingStatus.CANCELLED) {
            throw new BadRequestError(`Cannot cancel booking with status: ${booking.status}`);
        }

        // Check cancellation policy (e.g., 24 hours before)
        const hoursBefore = 24;
        const cancellationDeadline = new Date(booking.date);
        cancellationDeadline.setHours(cancellationDeadline.getHours() - hoursBefore);

        if (new Date() > cancellationDeadline) {
            throw new BadRequestError(
                `Bookings can only be cancelled at least ${hoursBefore} hours before the activity`
            );
        }

        return await this.updateBookingStatus(id, BookingStatus.CANCELLED);
    }

    /**
     * Update booking details
     */
    async updateBooking(id: string, userId: string, data: UpdateBookingDTO): Promise<Booking> {
        const booking = await bookingRepository.findById(id);

        if (!booking) {
            throw new NotFoundError('Booking', id);
        }

        // Verify ownership
        if (booking.userId !== userId) {
            throw new NotFoundError('Booking', id);
        }

        // Only allow updates for pending bookings
        if (booking.status !== BookingStatus.PENDING) {
            throw new BadRequestError('Only pending bookings can be modified');
        }

        // Validate date if provided
        if (data.date && data.date <= new Date()) {
            throw new BadRequestError('Booking date must be in the future');
        }

        // Validate guests if provided
        if (data.guests && (data.guests < 1 || data.guests > 50)) {
            throw new BadRequestError('Number of guests must be between 1 and 50');
        }

        return await bookingRepository.update(id, data);
    }

    /**
     * Get booking statistics
     */
    async getBookingStats(userId?: string): Promise<BookingStats> {
        const where = userId ? { userId } : undefined;

        const [total, upcoming, completed, cancelled, pending, totalRevenue] = await Promise.all([
            bookingRepository.count(where),
            bookingRepository.countByStatus(BookingStatus.CONFIRMED, userId),
            bookingRepository.countByStatus(BookingStatus.COMPLETED, userId),
            bookingRepository.countByStatus(BookingStatus.CANCELLED, userId),
            bookingRepository.countByStatus(BookingStatus.PENDING, userId),
            bookingRepository.getTotalRevenue(where)
        ]);

        return {
            total,
            upcoming,
            completed,
            cancelled,
            pending,
            totalRevenue
        };
    }

    /**
     * Get upcoming bookings
     */
    async getUpcomingBookings(userId?: string): Promise<Booking[]> {
        return await bookingRepository.findUpcoming(userId);
    }

    /**
     * Get past bookings
     */
    async getPastBookings(userId?: string): Promise<Booking[]> {
        return await bookingRepository.findPast(userId);
    }

    /**
     * Get recent bookings (admin)
     */
    async getRecentBookings(limit: number = 5) {
        return await bookingRepository.findRecent(limit);
    }

    /**
     * Delete booking (admin only)
     */
    async deleteBooking(id: string): Promise<void> {
        const exists = await bookingRepository.exists(id);
        if (!exists) {
            throw new NotFoundError('Booking', id);
        }

        await bookingRepository.delete(id);
    }

    /**
     * Validate status transition
     */
    private validateStatusTransition(currentStatus: BookingStatus, newStatus: BookingStatus): void {
        const validTransitions: Record<BookingStatus, BookingStatus[]> = {
            [BookingStatus.PENDING]: [BookingStatus.CONFIRMED, BookingStatus.CANCELLED],
            [BookingStatus.CONFIRMED]: [BookingStatus.COMPLETED, BookingStatus.CANCELLED],
            [BookingStatus.COMPLETED]: [], // Cannot change from completed
            [BookingStatus.CANCELLED]: []  // Cannot change from cancelled
        };

        const allowedStatuses = validTransitions[currentStatus] || [];

        if (!allowedStatuses.includes(newStatus)) {
            throw new BadRequestError(
                `Cannot transition from ${currentStatus} to ${newStatus}`
            );
        }
    }
}

