/**
 * Email Service
 * Handles sending emails for bookings, confirmations, and notifications
 * Uses Nodemailer (Gmail) for email delivery
 */

import nodemailer, { type Transporter } from 'nodemailer';

interface EmailOptions {
    to: string;
    subject: string;
    html: string;
    text?: string;
}

export class EmailService {
    private transporter: Transporter | null = null;
    private fromEmail: string;
    private adminEmail: string | null;

    constructor() {
        // In Next.js, environment variables need to be accessed at runtime, not in constructor
        // We'll initialize Nodemailer lazily when sending emails
        const gmailUser = process.env.GMAIL_USER;
        this.fromEmail = gmailUser ? `Explore Marrakesh <${gmailUser}>` : 'Explore Marrakesh <no-reply@example.com>';
        this.adminEmail = gmailUser || null;
    }

    private getTransporter(): Transporter | null {
        if (this.transporter) {
            return this.transporter;
        }

        const user = process.env.GMAIL_USER;
        const pass = process.env.GMAIL_APP_PASSWORD;

        if (!user || !pass) {
            console.warn('ΓÜá∩╕Å Gmail email credentials not found in environment variables. Emails will be logged to console only.');
            console.warn('ΓÜá∩╕Å Make sure GMAIL_USER and GMAIL_APP_PASSWORD are set in .env and restart the server.');
            return null;
        }

        try {
            this.transporter = nodemailer.createTransport({
                service: 'gmail',
                auth: {
                    user,
                    pass
                }
            });
            console.log('Γ£à Nodemailer Gmail service initialized successfully');
            return this.transporter;
        } catch (error) {
            console.error('Γ¥î Failed to initialize Nodemailer transport:', error);
            return null;
        }
    }

    /**
     * Send an email using Nodemailer
     */
    private async sendEmail(options: EmailOptions): Promise<void> {
        const transporter = this.getTransporter();

        if (!transporter) {
            console.log('≡ƒôº Email would be sent (Gmail not configured):', {
                to: options.to,
                subject: options.subject,
            });
            return;
        }

        try {
            console.log('≡ƒôº Attempting to send email via Gmail:', {
                to: options.to,
                subject: options.subject,
                from: this.fromEmail
            });

            const info = await transporter.sendMail({
                from: this.fromEmail,
                to: options.to,
                subject: options.subject,
                html: options.html,
                text: options.text || options.html.replace(/<[^>]*>/g, ''),
            });

            console.log('Γ£à Email sent successfully via Gmail:', {
                to: options.to,
                subject: options.subject,
                messageId: info.messageId,
                from: this.fromEmail
            });
        } catch (error: any) {
            console.error('Γ¥î Error sending email:', {
                error: error,
                message: error?.message,
                stack: error?.stack,
                to: options.to,
                subject: options.subject
            });
            throw error;
        }
    }

    private getAppBaseUrl(): string {
        const baseUrl = process.env.NEXT_PUBLIC_APP_URL || process.env.NEXTAUTH_URL || '';
        return baseUrl.replace(/\/$/, '');
    }

    private buildAppUrl(path: string): string {
        if (/^https?:\/\//i.test(path)) {
            return path;
        }

        const normalizedPath = path.startsWith('/') ? path : `/${path}`;
        const baseUrl = this.getAppBaseUrl();
        return baseUrl ? `${baseUrl}${normalizedPath}` : normalizedPath;
    }

    private escapeHtml(value: string): string {
        return value
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }

